        'intros' => [
            'custom_fields' => 'Buat detail tambahan yang dibutuhkan suatu jenis tiket - misalnya tanggal mulai dan nama pengguna pada karyawan baru - lalu pilih tipe tiket mana yang memakainya. Setiap bidang menentukan sendiri apakah wajib diisi saat tiket dicatat, saat ditutup, atau keduanya, dan apakah peminta ditanya di portal.',
            'checklists' => 'Daftar periksa dapat menandai langkah sebagai wajib. Ini menentukan apa yang terjadi jika seseorang menutup tiket sebelum langkah-langkah tersebut dicentang.',
            'mandatory_fields' => 'Pilih bidang tiket mana yang wajib diisi sebelum tiket ditutup, dan apa yang terjadi saat seseorang menutup tiket dengan salah satunya kosong. Aturan ini berlaku di mana pun tiket dapat ditutup: layar tiket, tindakan massal, REST API, dan alur kerja.',
            'departments' => 'Departemen mengelompokkan dan mengarahkan tiket ke bagian organisasi Anda yang tepat — buat departemen yang digunakan service desk Anda untuk mengategorikan dan menugaskan pekerjaan.',
            'teams' => 'Tim menentukan departemen mana yang dapat diakses analis. Tetapkan departemen ke tim, lalu tetapkan analis ke tim untuk mengatur akses mereka.',
            'ticket_types' => 'Tipe tiket mengklasifikasikan jenis suatu permintaan (mis. Insiden, Permintaan Layanan) — tentukan tipe yang dapat diatur analis pada tiket.',
            'ticket_origins' => 'Asal tiket mencatat bagaimana tiket masuk (mis. Email, Telepon, Portal) — tentukan asal yang dapat dipilih analis.',
            'mailboxes' => 'Kotak surat menghubungkan FreeITSM ke akun email sehingga pesan masuk menjadi tiket dan balasan dikirim keluar — tambahkan dan autentikasi kotak surat yang dipantau service desk Anda.',
            'privacy' => 'Tiket tidak hanya berisi percakapan Anda dengan orang yang mengajukannya. Meneruskan ke pemasok, atau menyertakan rekan kerja, menaruh pesan itu di tiket yang sama — dan balasan mereka juga masuk ke sana. Ini menentukan seberapa banyak hal itu yang dilihat peminta di portal swalayan.',
            'indexing' => 'Teks di dalam lampiran dibaca agar dapat dicari. File Word, Excel, PowerPoint, dan teks biasa dibaca oleh FreeITSM sendiri, begitu file diterima. PDF, file Office lama, dan dokumen hasil pindai memerlukan layanan pembaca dokumen terpisah — siapkan di <strong>Sistem &rarr; Integrasi &rarr; Apache Tika</strong> — dan karena prosesnya jauh lebih lama, file tersebut dibaca di latar belakang. Kedua sakelar ini menentukan kapan pekerjaan latar belakang itu berjalan.',
            'merge_behaviour' => 'Ketika dua tiket ternyata membahas hal yang sama, analis dapat menggabungkannya. Pengaturan ini menentukan dampaknya terhadap nomor referensi tiket yang dipegang peminta, dan apa yang terjadi pada percakapannya. Pengaturan ini berlaku untuk semua orang — penggabungan mengubah apa yang dilihat pelanggan, sehingga dua analis pada kotak surat yang sama tidak boleh berbeda pendapat tentangnya.',
            'reply_templates' => 'Respons siap pakai yang dapat disisipkan analis ke dalam balasan tanpa mengetik ulang. Ini adalah templat bersama yang dilihat seluruh tim — templat pribadi milik analis disimpan dari jendela balasan dan tidak tercantum di sini.',
            'rota_shifts' => 'Shift adalah templat pola kerja (mis. Pagi, Sore, Siaga) yang ditetapkan kepada analis pada jadwal staf — tentukan di sini sebelum menyusun jadwal.',
            'analysts' => 'Analis adalah staf yang masuk dan menangani tiket — tambahkan mereka, atur ulang kata sandi, dan tetapkan ke tim untuk mengatur akses mereka.',
            'general' => 'Pengaturan umum mengatur perilaku tiket - membuka kembali, menunda, dan berapa lama pesan dan utas ditampilkan.',
            'statuses' => 'Keadaan alur kerja yang dapat dimiliki tiket. Status yang ditandai <em>Ditutup</em> dihitung sebagai akhir — dipakai oleh laporan, penghitung watchtower, dan pengisian otomatis waktu penutupan saat penugasan. Tepat satu status menjadi default untuk tiket baru.',
            'priorities' => 'Tingkat prioritas yang ditampilkan pada tiket. Tepat satu prioritas menjadi default untuk tiket baru.',
            'rota_locations' => 'Di mana setiap analis bekerja pada hari tertentu — dipakai oleh jadwal staf dan ditampilkan sebagai lencana berwarna pada setiap entri. Tepat satu lokasi menjadi default untuk entri jadwal baru.',
            'email_templates' => 'Respons email otomatis yang dipicu oleh peristiwa tiket. Hanya templat aktif pertama untuk setiap peristiwa yang digunakan.',
        ],
        'messaging' => [
            'channels_heading' => 'Kanal pesan',
            'channels_intro' => 'Biarkan pelanggan mengobrol dengan analis lewat WhatsApp — setiap pesan menjadi tiket, sama seperti email. Tambahkan kanal di bawah, lalu tempel <strong>URL webhook</strong>-nya ke penyedia Anda (Twilio atau Meta) agar pesan masuk sampai ke instalasi ini.',
            'base_url_label' => '<strong>URL dasar publik</strong>',
            'base_url_placeholder' => 'https://your-domain.com  (atau alamat ngrok Anda saat pengujian)',
            'base_url_help' => 'Alamat yang dipakai penyedia untuk menjangkau instalasi ini. Atur, dan URL webhook di bawah siap disalin-tempel. Kosongkan untuk memakai alamat yang sedang Anda buka. Menguji secara lokal? Jalankan <code>ngrok http 80</code> dan tempel alamat <code>https://…ngrok-free.dev</code> yang ditampilkannya.',
            'templates_heading' => 'Templat pesan',
