        'sla' => [
            'heading' => 'Service level agreement',
            'intro' => 'SLA yang memperhitungkan jam kerja dengan target respons dan penyelesaian per prioritas. Jam berhenti pada status yang ditandai "Jeda SLA" di <a href="#" onclick="event.preventDefault();switchTab(\'statuses\');">tab Status</a>. Lihat <a href="https://github.com/edmozley/freeitsm/blob/main/docs/sla.md" target="_blank">catatan desain</a>.',
