            'enforce_from' => 'Terapkan SLA mulai dari',
            'enforce_from_help' => 'Kosongkan untuk <strong>menonaktifkan penerapan SLA sepenuhnya</strong>. Atur ke tanggal dan waktu, dan hanya tiket yang dibuat pada atau setelah titik itu yang dievaluasi &mdash; berguna untuk mengecualikan tiket yang sudah ada saat pertama kali mengaktifkan SLA.',
