            'save_global' => 'Simpan pengaturan global',
            'targets_heading' => 'Target SLA per prioritas',
            'targets_intro' => 'Waktu respons dan penyelesaian untuk setiap prioritas tiket. Waktu dalam menit (60 = 1 jam, 240 = 4 jam, 1440 = 1 hari). Kalender menentukan jam kerja yang menjadi acuan jam berjalan. Kosongkan untuk melewati target tersebut.',
            'col_priority' => 'Prioritas',
