            'col_calendar' => 'Kalender',
            'col_save' => 'Simpan',
            'calendars_heading' => 'Kalender bisnis',
            'calendars_intro' => 'Tentukan jam kerja, zona waktu, dan daftar hari libur. Kalender dirujuk oleh target SLA (di atas) dan oleh masing-masing prioritas. Satu kalender menjadi default untuk prioritas baru.',
            'col_name' => 'Nama',
            'col_timezone' => 'Zona waktu',
            'col_hours' => 'Jam',
            'col_holidays' => 'Hari libur',
            'col_default' => 'Default',
            'col_actions' => 'Tindakan',
            'notifs_heading' => 'Notifikasi pelanggaran',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">Cara kerja aturan notifikasi</strong>Setiap aturan memiliki empat bagian: <strong>cakupan</strong>, <strong>pemicu</strong>, <strong>target</strong>, dan daftar <strong>penerima</strong>.<br><br><strong>Cakupan</strong> dapat berupa <em>Default</em> (aturan berlaku untuk tiket di setiap departemen) atau <em>departemen tertentu</em> (aturan hanya berlaku untuk tiket di departemen itu).<br>Saat tiket dievaluasi, sistem lebih dulu mencari aturan yang cocok dengan departemennya &mdash; jika ada, aturan itu yang dipakai dan default diabaikan. Jika tidak ada aturan khusus departemen, aturan default dipakai. Dengan cara ini Anda dapat menetapkan default yang masuk akal untuk semua departemen, lalu membuat pengecualian bila satu tim memiliki kebutuhan eskalasi yang berbeda.<br><br><strong>Pemicu</strong> adalah <em>Peringatan</em> (tiket telah melewati ambang peringatan &mdash; potensi pelanggaran mendekat) atau <em>Pelanggaran</em> (tiket kini telah melampaui target SLA-nya &mdash; pelanggaran sebenarnya). Masing-masing adalah aturan tersendiri, sehingga Anda dapat memberi tahu orang yang berbeda untuk peringatan dan pelanggaran.<br><br><strong>Target</strong> adalah jam SLA mana yang dipantau &mdash; <em>Respons</em>, <em>Penyelesaian</em>, atau <em>Keduanya</em>.<br><br><strong>Penerima</strong> dapat berupa kombinasi apa pun dari: penerima tugas tiket saat ini, setiap analis di tim departemen tiket, satu analis bernama, dan/atau daftar alamat email bebas (berguna untuk kotak masuk bersama atau jembatan email Slack/Teams).<br><br><strong style="color:var(--warning-text, #92400e);">Tanpa aturan = tanpa email.</strong> Meskipun tiket melanggar, tidak ada yang dikirim sampai Anda menambahkan setidaknya satu aturan (mulai dengan pasangan Peringatan + Pelanggaran bercakupan Default agar semuanya tercakup).',
            'notifs_dedup' => 'Setiap tiket mengirim paling banyak satu email per target per pemicu &mdash; worker cron melacak apa yang sudah terkirim sehingga Anda tidak menerima duplikat.',
            'col_scope' => 'Cakupan',
            'col_trigger' => 'Pemicu',
            'col_target' => 'Target',
            'col_recipients' => 'Penerima',
            'col_active' => 'Aktif',
            'notifs_cron_note' => 'Worker cron yang mengirim email ini berada di <code>cron/sla_breach_check.php</code>. Lihat <code>docs/sla-cron-setup.md</code> untuk penyiapan Windows Task Scheduler + cron Linux.',
            'cron_heading' => 'Aktivitas cron',
            'cron_refresh' => 'Segarkan',
            'cron_intro' => '<span id="slaCronRunsLimit">20</span> pemanggilan terakhir cron pemeriksa pelanggaran (CLI dan HTTP). Termasuk permintaan yang ditolak (dibatasi laju, autentikasi gagal) sehingga sumber kebenaran yang sama mendukung pemeriksaan pembatasan laju dan audit keamanan. Dihapus otomatis setelah <strong><span id="slaCronRetentionDays">30</span> hari</strong>; interval minimum antar proses yang berhasil adalah <strong><span id="slaCronMinInterval">30</span> dtk</strong> (keduanya dapat dikonfigurasi di <code>system_settings</code>).',
