            'existing_note' => '<strong>Nomor yang sudah ada tidak berubah.</strong> Tiket yang ada mempertahankan referensinya, dan setiap referensi yang pernah diterbitkan FreeITSM tetap berfungsi &mdash; termasuk dalam balasan email lama. Jika Anda ingin tiket yang ada juga dinomori ulang, ada alat untuk itu di bawah. <strong>Angka Anda tidak akan habis:</strong> lebar yang Anda pilih adalah minimum, sehingga tiket 1.000.001 cukup mendapat satu angka lebih panjang tanpa merusak apa pun.',
