            'renumber_safety' => '<strong>Referensi lama tetap berfungsi.</strong> Setiap nomor yang pernah dimiliki tiket diingat, sehingga balasan terhadap email yang mengutip nomor lama tetap masuk ke tiket yang benar &mdash; persis seperti saat tiket digabungkan. Nomor yang sudah pensiun juga tidak pernah diberikan ke tiket lain. Namun ini tidak dapat dibatalkan, jadi lihat pratinjau terlebih dahulu.',
