            'group_older_help' => 'Di luar jumlah di bawah, pesan yang lebih lama dilipat menjadi satu baris yang dapat dibuka. Tiket yang panjang adalah masalah yang berbeda dari pesan yang panjang.',
            'group_show_label' => 'Biarkan sejumlah pesan terbaru ini tetap terbuka',
            'flag_duplicates_label' => 'Tunjukkan pesan yang sudah pernah masuk',
            'flag_duplicates_help' => 'Pengiriman ulang, pengiriman ganda, atau pesan pentalan yang membawa pesan asli dilipat dengan catatan yang menyebutkan pesan mana yang cocok. Tidak ada yang dihapus.',
            'team_folders_heading' => 'Folder tim',
            'team_folders_label' => 'Analis melihat',
            'team_folders_all' => 'Semua tim',
            'team_folders_mine' => 'Hanya tim tempat mereka berada',
            'team_folders_help' => 'Hanya mengubah daftar folder - tidak ada yang kehilangan akses ke tiket. Tim yang memegang tiket yang dapat dilihat analis tetap ditampilkan, sehingga jumlah folder tetap sesuai. Administrator selalu melihat semua tim.',
            'watch_heading' => 'Memantau tiket',
            'watch_help' => 'Hal yang diberitahukan kepada pemantau tiket. Pengaturan notifikasi masing-masing pemantau tetap berlaku di atasnya.',
            'watch_event_ticket_reply_received' => 'Peminta membalas',
            'watch_event_ticket_note_added' => 'Catatan ditambahkan',
            'watch_event_ticket_status_changed' => 'Status berubah',
            'watch_event_ticket_priority_changed' => 'Prioritas berubah',
            'watch_event_ticket_assigned' => 'Tiket ditugaskan ulang',
            'watch_event_sla_warning' => 'Mendekati target SLA',
            'watch_event_sla_breached' => 'Melanggar target SLA',
            'ai_heading' => 'Alat bantu baca AI',
            'ai_desc' => 'Opsional, dan nonaktif sampai Anda mengaktifkannya: berbeda dari yang lain di halaman ini, fitur ini memakai penyedia AI Anda sendiri dan berbiaya per penggunaan. Penyedia, model, dan API key dikonfigurasi sekali di tab Pembersihan balasan. Apa pun yang ditulis AI tidak pernah menggantikan tiket — percakapan tetap persis di tempatnya, secara utuh.',
            'ai_summary_label' => 'Simpan ringkasan AI singkat di bagian atas setiap tiket',
            'ai_summary_help' => 'Beberapa baris yang menyatakan posisi tiket, ditulis atas permintaan dan dijaga tetap terbaru. Selalu menampilkan kapan ditulis, seberapa banyak yang dibaca, dan seberapa jauh percakapan berlanjut sejak itu. Setiap versi disimpan, sehingga ringkasan yang lebih buruk tidak pernah menghapus yang lebih baik.',
            'ai_auto_label' => 'Segarkan otomatis setelah sejumlah pesan baru ini',
            'ai_auto_help' => '0 berarti tidak pernah — tombol Segarkan menjadi satu-satunya cara, dan tidak ada biaya yang dikenakan tanpa ada yang meminta. Penyegaran hanya terjadi saat analis membuka tiket, sehingga antrean sibuk yang tidak dibaca siapa pun tidak berbiaya apa-apa.',
            'ai_max_label' => 'Jumlah pesan yang dibaca',
            'ai_max_help' => 'Seberapa jauh ke belakang ringkasan membaca. Tiket yang lebih panjang dibaca dari ujung terbarunya, dan ringkasan menyatakannya alih-alih menggambarkan awal yang tidak pernah dilihatnya.',
            'ai_notes_label' => 'Izinkan membaca catatan internal',
            'ai_notes_help' => 'Catatan internal sering berisi apa yang sebenarnya sudah dicoba. Catatan itu khusus staf dalam kedua kasus — ringkasan tidak pernah ditampilkan kepada peminta — tetapi nonaktifkan ini jika catatan di tim Anda berisi hal-hal yang tidak boleh keluar.',
            'ai_read_label' => 'Tawarkan "Bacakan" pada tiket',
            'ai_confidential_label' => 'Tiket rahasia dan AI',
            'ai_confidential_block' => 'Jangan pernah kirim ke AI (disarankan)',
            'ai_confidential_allow' => 'Perlakukan seperti tiket lainnya',
            'ai_confidential_help' => 'Mencakup setiap fitur AI yang membaca tiket: ringkasan, Bacakan, pembersihan balasan, Tanya AI, ringkasan penggabungan, tulisan pengetahuan, ringkasan kanal, analisis masalah, dan bot war room. Tiket rahasia tidak dikirim, atau - bila banyak tiket dibaca sekaligus - dikecualikan atau hanya ditampilkan berdasarkan nomornya.',
            'ai_read_help' => 'Tombol yang membaca seluruh tiket dan memberi Anda penjelasan singkat: apa yang terjadi, apa yang belum terselesaikan, dan apa yang akan dilakukannya selanjutnya. Diminta dan dibaca sekali, tidak disimpan di mana pun.',
            'reopen_help' => 'Berlaku di mana pun peminta kembali — portal swalayan, balasan terhadap email notifikasi Anda, WhatsApp, atau web chat. Tiket kembali ke status terbuka pertama Anda. Hanya tiket pada status yang ditandai tertutup yang terpengaruh (atur status mana di bawah Status).',
        ],
        'privacy' => [
            'third_party_label' => 'Pesan yang dikirim ke selain peminta',
            'opt_hide' => 'Sembunyikan dari peminta',
            'opt_hide_help' => 'Pesan dan lampirannya sama sekali tidak muncul di portal peminta. Disarankan: kebanyakan orang mengira meneruskan tiket ke pemasok bersifat pribadi.',
            'opt_no_attachments' => 'Tampilkan pesan, tetapi tanpa lampirannya',
            'opt_no_attachments_help' => 'Peminta dapat melihat bahwa Anda menghubungi pihak lain dan apa yang ditulis, tetapi tidak dapat mengunduh berkas terlampir apa pun.',
            'opt_show' => 'Tampilkan semuanya',
            'opt_show_help' => 'Peminta melihat seluruh tiket persis seperti analis Anda, termasuk penerusan dan balasan pihak ketiga. Inilah perilaku sebelum pengaturan ini ada.',
            'always_visible_note' => '<strong>Selalu terlihat oleh peminta:</strong> pesan mereka sendiri, dan balasan apa pun yang ditujukan kepada mereka. <strong>Tidak pernah terlihat:</strong> catatan internal — disembunyikan dari portal terlepas dari pengaturan ini. Pesan di WhatsApp dan web chat selalu ditampilkan, karena percakapan tersebut pada dasarnya antara peminta dan tim Anda.',
            'timezone' => 'Zona waktu',
            'timezone_help' => 'Digunakan untuk menampilkan tanggal dan waktu di seluruh sistem.',
        ],
        'reply_cleanup' => [
            'intro1' => 'Saat analis mengetik balasan kasar di modal penulisan tiket, tombol <strong>✨ Bersihkan</strong> akan menulis ulang menjadi email yang terformat dengan baik — menambahkan sapaan "Yth. [nama],", memperbaiki tata bahasa, menerapkan nada yang Anda pilih di bawah, dan menutup dengan "Hormat kami,". Tombol ini <strong>tidak</strong> akan mengarang detail teknis atau menambah-nambah isi.',
            'intro2' => 'Fitur ini menggunakan API key Anthropic tersendiri (terpisah dari RFP AI dan Knowledge AI) sehingga penggunaannya muncul sebagai baris tersendiri di dasbor penagihan Anthropic.',
            'tone' => 'Nada',
            'tone_friendly' => 'Ramah (default)',
            'tone_formal' => 'Formal',
            'tone_brief' => 'Singkat',
            'tone_help' => 'Diterapkan pada setiap pembersihan kecuali diubah di sini.',
            'custom_label' => 'Instruksi kustom <span style="color: #999; font-weight: normal;">(opsional)</span>',
            'custom_placeholder' => 'misal, Selalu tutup dengan \'Terima kasih banyak,\'&#10;Sebut perusahaan sebagai \'BillCorp\'&#10;Gunakan ejaan bahasa Inggris Britania sepanjang waktu',
            'custom_help' => 'Ditambahkan ke system prompt yang ditampilkan di sebelah kanan. Gunakan untuk penyesuaian khusus organisasi (variasi penutup, nama perusahaan, preferensi bahasa). Aturan keamanan yang ketat dan format keluaran tetap diutamakan.',
            'prompt_summary' => 'Lihat system prompt (hanya baca)',
            'prompt_panel_intro' => 'Ini adalah system prompt lengkap yang dikirim ke Claude pada setiap pembersihan. Nama pada sapaan berbeda per tiket; nada mencerminkan pilihan Anda di sebelah kiri. Instruksi kustom Anda (jika ada) ditambahkan di akhir saat dijalankan — tidak ditampilkan di sini, ubah di kotak teks sebelah kiri.',
        ],
        'csat_tab' => [
            'intro1' => 'Saat tiket ditutup, kirim email survei singkat kepada peminta yang meminta mereka menilai pengalamannya 1&ndash;5. Respons dicatat atas nama analis yang menutup tiket sehingga Anda dapat menarik tren CSAT per analis, dan tampil sebagai widget di dasbor.',
            'intro2' => 'Email survei dikonfigurasi di <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">Templat email</a> &mdash; buat templat dengan peristiwa <strong>Survei CSAT</strong> dan sisipkan <code>[csat_link]</code> di isi untuk memasukkan URL penilaian sekali pakai.',
            'mode_off' => 'Nonaktif',
            'mode_off_help' => 'Tidak ada email survei yang dikirim.',
            'mode_auto' => 'Otomatis saat ditutup',
            'mode_auto_help' => 'Survei dikirim otomatis saat tiket berpindah ke status tertutup mana pun.',
            'mode_manual' => 'Manual saja',
            'mode_manual_help' => 'Analis mengklik <em>Umpan balik</em> dari bilah alat tiket saat ingin bertanya.',
            'delay_help' => 'Tunggu sekian menit setelah penutupan sebelum mengirim. <code>0</code> = segera. Berguna jika Anda ingin pengguna memastikan perbaikan benar-benar bertahan sebelum diminta menilai.',
            'reminder' => 'Kirim satu pengingat jika survei tidak dijawab',
            'reminder_hours' => 'Ingatkan setelah (jam)',
            'reminder_help' => 'Paling banyak satu pengingat, lewat email, dengan tautan yang sama - sehingga email mana pun berfungsi dan hanya satu penilaian yang disimpan. Tidak dikirim jika tiket telah dibuka kembali. Memakai templat email <strong>Pengingat CSAT</strong> jika Anda memilikinya, jika tidak, templat survei dipakai lagi. Mengaktifkan ini tidak mengingatkan orang tentang survei lama: hanya yang pengingatnya jatuh tempo mulai sekarang.',
            'one_per_ticket' => 'Satu survei per tiket',
            'one_per_ticket_help' => 'Jika aktif, tiket yang dibuka kembali lalu ditutup hanya mendapat survei lagi bila analis memicunya secara manual &mdash; mencegah survei bertubi-tubi pada tiket yang bermasalah.',
            'in_channel' => 'Tanya pelanggan chat di chat mereka',
            'in_channel_help' => 'Pelanggan yang menulis lewat WhatsApp, Telegram, Slack, Teams, atau Mattermost ditanya di chat tersebut &mdash; dengan tombol jika aplikasinya punya, &ldquo;balas 1 sampai 5&rdquo; jika tidak &mdash; alih-alih lewat email. WhatsApp hanya selama jendela 24 jamnya terbuka; selain itu, dan jika pesan chat gagal, survei email yang dipakai.',
            'scale_stars' => 'Bintang',
            'scale_emojis' => 'Emoji',
            'scale_help' => 'Kedua opsi menyimpan angka 1&ndash;5 yang sama, sehingga dasbor dan rata-rata bekerja sama pada keduanya &mdash; ini hanya mengubah tampilan halaman survei itu sendiri.',
