    'help' => [
        'case' => [
            'nav' => 'Laporan kasus',
            'heading' => 'Laporan kasus',
            'intro' => 'Ketika peninjau atau auditor menanyakan bagaimana suatu kasus ditangani, <strong>Ekspor</strong> menyatukan tiket, percakapannya, dan tugas yang mengerjakannya ke dalam satu dokumen yang dapat dicetak - sehingga tidak ada yang perlu menyalinnya secara manual.',
            'step1' => '<strong>Buka tiket</strong> dan pilih <strong>Ekspor</strong> di bilah alatnya (di bawah <strong>Lainnya</strong> jika panel baca sempit). Laporan terbuka di tab baru. Untuk tugas tanpa tiket, gunakan tombol dokumen di bagian atas jendela tugas.',
            'step2' => '<strong>Centang apa yang disertakan</strong> di panel kiri. Laporan digambar ulang saat Anda mencentang, dan tidak ada yang dicatat selama Anda memilih.',
            'step3' => '<strong>Pilih tata letak</strong>: halaman sampul, halaman daftar isi, setiap bagian di halaman baru, dan header dengan nomor halaman.',
            'step4' => '<strong>Cetak</strong>, lalu pilih <em>Simpan sebagai PDF</em> di dialog cetak. Hapus centang <em>Header dan footer</em> bawaan peramban - laporan mencetak miliknya sendiri.',
            'contents' => '<strong>Isinya:</strong> ikhtisar tiket (dengan bidang kustom, aset yang ditautkan, configuration item, dan tiket terkait); setiap pesan, dari yang terlama; catatan; daftar periksa tiket; setiap tugas yang ditautkan beserta subtugas, hasil daftar periksa dan catatan pengecualian, jawaban formulir, prosedur yang diikuti, tindak lanjut, dan komentar; riwayat tiket dan setiap tugas; serta indeks dokumen dan lampiran email, dengan sidik jari yang dicatat FreeITSM untuk setiap dokumen.',
            'layout' => '<strong>Tata letak:</strong> halaman daftar isi memuat setiap bagian dan tugas, dan setiap entri berupa tautan di PDF yang disimpan. Header dan nomor halaman (<em>Halaman 3 dari 12</em>) memerlukan Chrome atau Edge terbaru; peramban lain mencetak laporan tanpanya.',
            'who' => '<strong>Siapa melihat apa:</strong> laporan hanya menampilkan yang dapat Anda lihat di layar. Tugas, aset, configuration item, tiket terkait, dokumen, dan jawaban formulir masing-masing diperiksa dengan aturannya sendiri, dan apa pun yang tidak boleh Anda lihat <em>dihitung</em> - tidak pernah disebutkan - agar pembaca tahu ada yang dihilangkan. <strong>Catatan internal dihilangkan kecuali Anda mencentangnya</strong>, karena laporan biasanya keluar dari tim.',
            'recorded' => '<strong>Yang dicatat:</strong> pencetakan menulis baris <em>Laporan kasus</em> pada jejak audit tiket berisi siapa yang mencetak dan bagian mana yang tercakup. Pratinjau dan mengubah pilihan tidak mencatat apa pun.',
            'note' => 'Laporan kasus adalah salinan catatan, bukan tulisan ulang: tidak ada yang diubah kata-katanya atau diringkas, gambar di dalam email tidak ditampilkan ulang, berkas didaftar dan tidak disertakan, dan hanya riwayat yang benar-benar dicatat FreeITSM yang muncul. Bagian yang tidak dapat dibaca menyatakannya dengan warna merah, bukan tampak kosong.',
        ],
        'workspace' => [
            'nav' => 'Ruang kerja dan tabel tiket',
            'heading' => 'Ruang kerja dan tabel tiket',
            'intro' => 'Dua cara lain untuk mengerjakan tiket, keduanya opsional. <strong>Ruang kerja</strong> menata satu tiket untuk dikerjakan, bukan sekadar dibaca. <strong>Tabel tiket</strong> menampilkan daftar tiket sebagai tabel yang dapat Anda filter, urutkan, dan simpan.',
            'ws_title' => 'Ruang kerja',
            'ws_what' => 'Di ruang kerja, properti tiket berada di kolom kiri, dan <strong>Percakapan</strong>, <strong>Pekerjaan</strong> (daftar periksa dan tugas yang ditautkan), <strong>Tautan</strong>, <strong>Waktu dan SLA</strong>, serta <strong>Riwayat</strong> menjadi tab di sebelahnya. Bilah alat dan setiap kontrol sama dengan yang ada di panel baca - hanya letaknya yang berubah. <strong>Daftar periksa</strong> tiket mencantumkan setiap langkah dengan kotak centangnya di tab Pekerjaan; <strong>Ciutkan</strong> hanya menampilkan langkah berikutnya (diingat di peramban Anda), dan <strong>Pop out</strong> tetap membukanya di jendela sendiri.',
            'ws_admin' => '<strong>Administrator mengaktifkannya</strong> di <strong>Tiket &rarr; Pengaturan &rarr; Umum &rarr; Ruang kerja tiket</strong>: <em>Nonaktif</em> (default), <em>Hanya tiket yang dijadikan ruang kerja</em>, atau <em>Semua tiket</em>.',
            'ws_make' => '<strong>Menjadikan tiket sebagai ruang kerja:</strong> pada pengaturan tengah, buka tiket dan pilih <strong>Lainnya &rarr; Jadikan ruang kerja</strong> (dan <strong>Kembali ke panel baca</strong> untuk membatalkannya). Ini melekat pada tiket, sehingga semua yang mengerjakannya melihatnya dengan cara yang sama, dan dicatat di riwayat tiket.',
            'ws_own' => '<strong>Pilihan Anda sendiri:</strong> setelah aktif, <strong>Gunakan ruang kerja</strong> di menu filter daftar, atau di <strong>Sistem &rarr; Preferensi</strong>, menonaktifkannya hanya untuk Anda. Tiket yang dijadikan ruang kerja kemudian menampilkan lencana kecil <em>Ruang kerja</em>, sehingga Anda tahu rekan sedang mengerjakannya dengan cara itu.',
            'ws_checklist' => '<strong>Daftar periksa tiket mencantumkan setiap langkah:</strong> di tab <strong>Pekerjaan</strong>, daftar periksa menampilkan semua langkahnya dengan kotak centang. <strong>Ciutkan</strong> mengecilkannya menjadi langkah berikutnya saja, seperti yang ditampilkan panel baca, dan <strong>Luaskan</strong> mengembalikan sisanya - peramban Anda mengingat pilihan Anda. <strong>Pop out</strong> tetap membuka daftar periksa lengkap di jendela.',
            'ws_tasks' => '<strong>Tugas yang ditautkan terbuka di tempat:</strong> klik tugas di tab <strong>Pekerjaan</strong> dan editornya sendiri terbuka di sana - termasuk daftar periksa, formulir, prosedur, subtugas, komentar, dan dokumen. <strong>Buka terpisah</strong> membukanya di jendela sendiri seperti sebelumnya; Ctrl-klik melakukan hal yang sama. Anda memerlukan akses ke Tugas untuk mengubahnya.',
            'ws_safe' => '<strong>Tidak ada yang setengah diketik hilang:</strong> berpindah ke tiket lain, atau menonaktifkan ruang kerja, dengan balasan, catatan, atau perubahan tugas yang belum disimpan akan bertanya dulu kepada Anda, dan menunggu apa pun yang masih disimpan.',
            'tb_title' => 'Tabel tiket',
            'tb_what' => 'Pilih <strong>Tabel</strong> sebagai ganti <strong>Pesan</strong> di baris tindakan di bagian atas Tiket (atau di <strong>Sistem &rarr; Preferensi</strong>). Folder tempat Anda berada menjadi filter tabel; pilih kolom, filter dan urutkan, cari, dan telusuri daftar 25, 50, atau 100 tiket sekaligus. <strong>Simpan tampilan</strong> menyimpan tata letak untuk Anda sendiri, tim Anda, atau semua orang.',
            'tb_same' => 'Klik, Ctrl- dan Shift-klik, klik kanan, seret ke folder, dan tindakan massal semuanya bekerja seperti di daftar pesan, dan tabel tidak pernah menampilkan tiket yang tidak akan ditampilkan daftar.',
            'tb_export' => '<strong>Ekspor CSV:</strong> tombol CSV mengekspor <em>setiap</em> tiket yang cocok, bukan hanya satu halaman, dengan kolom yang sedang Anda tampilkan. Siapa yang boleh memakainya diatur di <strong>Tiket &rarr; Pengaturan &rarr; Umum &rarr; Siapa yang dapat mengekspor daftar tiket</strong>: hanya administrator (default), siapa pun yang memiliki Tiket, atau tidak ada. Tombol tidak ditampilkan kepada siapa pun yang tidak diizinkan.',
        ],
        'page_title' => 'Service Desk - Panduan Tiket',
        'sidebar_title' => 'Panduan',
        'hero_title' => 'Panduan modul Tiket',
        'hero_sub' => 'Catat, lacak, dan selesaikan permintaan dukungan TI dari satu kotak masuk berbasis folder &mdash; dibuat untuk tim service desk.',
        'nav' => [
            'overview' => 'Ikhtisar',
            'inbox' => 'Kotak masuk',
            'working_with_tickets' => 'Bekerja dengan tiket',
