        'overview' => [
            'heading' => 'Ikhtisar',
            'intro' => 'Modul Tiket adalah inti dari service desk TI Anda. Modul ini menyediakan antarmuka ala klien email untuk mengelola permintaan dukungan, insiden, dan tugas layanan. Tiket masuk dari pengguna akhir lewat email atau dibuat secara manual, lalu analis menanganinya menggunakan folder, prioritas, dan pengatur waktu SLA &mdash; semua yang Anda butuhkan untuk memberikan dukungan TI yang responsif.',
            'card_inbox_title' => 'Kotak masuk',
            'card_inbox_body' => 'Kotak masuk berbasis folder yang meniru klien email. Jelajahi folder Tiket Saya, Belum ditugaskan, Semua Terbuka, dan Ditutup. Klik tiket mana pun untuk membuka panel baca dengan detail lengkap, riwayat, dan tindakan.',
            'card_dashboard_title' => 'Dasbor',
            'card_dashboard_body' => 'Buat dasbor pribadi dengan widget Chart.js yang dapat disesuaikan. Visualisasikan volume tiket, waktu respons, rincian kategori, dan beban kerja analis dengan grafik batang, pai, donat, dan garis.',
            'card_calendar_title' => 'Kalender',
            'card_calendar_body' => 'Lihat tiket pada kisi kalender berdasarkan tanggal dibuat, jatuh tempo, atau selesai. Dengan cepat temukan item yang terlambat dan rencanakan minggu Anda dengan melihat gambaran tiket sekilas.',
            'card_rota_title' => 'Jadwal',
            'card_rota_body' => 'Atur shift analis dan jadwal siaga. Lihat siapa yang tersedia kapan saja, rencanakan cakupan untuk akhir pekan dan hari libur, dan pastikan tidak ada tiket yang terabaikan.',
        ],
        'inbox' => [
            'heading' => 'Kotak masuk',
            'intro' => 'Kotak masuk adalah ruang kerja utama analis. Tata letaknya tiga panel &mdash; folder di kiri, daftar tiket di tengah, dan panel baca di kanan &mdash; sehingga Anda dapat memilah dan merespons tanpa pernah meninggalkan halaman.',
            'p_live' => '<strong>Kotak masuk memperbarui dirinya sendiri.</strong> Setiap menit kotak masuk memeriksa kotak surat Anda dan mencari hal baru pada tiket yang dapat Anda lihat &mdash; email yang dikumpulkan di latar belakang, pesan WhatsApp, Telegram, Slack, Teams, atau Mattermost, balasan dari rekan kerja &mdash; dan saat ada yang masuk, daftar dan jumlah folder disegarkan sendiri, seperti saat tombol segarkan ditekan. Tiket yang sedang Anda baca dan balasan yang sedang Anda ketik tidak diganggu.',
            'p_folders' => 'Panel folder mengelompokkan tiket secara logis. Setiap folder menampilkan jumlah belum dibaca sehingga Anda dapat langsung melihat pekerjaan baru:',
            'field_my' => '<strong>Tiket Saya</strong> &mdash; tiket yang ditugaskan kepada Anda. Ini antrean pribadi Anda dan tempat terbaik untuk memulai setiap hari.',
            'field_unassigned' => '<strong>Belum ditugaskan</strong> &mdash; tiket yang sudah masuk tetapi belum memiliki analis. Ambil item dari sini untuk menjadi penanggung jawabnya.',
            'field_all_open' => '<strong>Semua Terbuka</strong> &mdash; setiap tiket yang belum ditutup, siapa pun pemiliknya. Berguna bagi manajer dan ketua tim yang memantau volume keseluruhan.',
            'field_closed' => '<strong>Ditutup</strong> &mdash; tiket yang sudah teratasi. Cari di sini saat Anda perlu merujuk solusi lama atau membuka kembali masalah.',
            'field_dept' => '<strong>Folder departemen</strong> &mdash; tiket yang dikelompokkan menurut departemen (mis. TI, SDM, Keuangan). Departemen dikonfigurasi di Pengaturan dan muncul otomatis sebagai subfolder.',
            'switch_heading' => '<strong>Beralih antara pengelompokan Departemen dan Analis</strong>',
            'switch_body' => 'Tombol dua pilihan kecil di bagian atas panel folder beralih antara dua tampilan dari data yang sama. Pengelompokan <strong>Departemen</strong> (default) mencantumkan tiket di bawah setiap departemen dengan subfolder status di dalamnya; pengelompokan <strong>Analis</strong> membaliknya sehingga setiap folder tingkat atas mewakili antrean pribadi seorang analis dengan subfolder status di dalamnya. Folder <strong>Belum ditugaskan</strong> menyesuaikan diri dengan tiap tampilan &mdash; di tampilan Departemen folder ini mencantumkan tiket tanpa departemen; di tampilan Analis folder ini mencantumkan tiket tanpa penerima tugas &mdash; sehingga Anda selalu dapat melihat apa yang perlu diambil. Pilihan Anda disimpan per analis sehingga setiap anggota tim tetap memakai tampilan yang disukainya di semua sesi.',
            'p_actions' => 'Di atas daftar tiket, ada empat tombol tindakan: <strong>Baru</strong> untuk membuat tiket, <strong>Cari</strong> untuk menemukan tiket berdasarkan kata kunci, referensi, atau peminta, <strong>Filter</strong> untuk mempersempit tampilan, dan <strong>Segarkan</strong> untuk memuat ulang folder saat ini.',
            'filter_body' => 'Tombol <strong>Filter</strong> (corong) mempersempit folder dan daftar sekaligus, apa pun cara pengelompokannya. <strong>Saya</strong> hanya menampilkan tiket yang ditugaskan kepada Anda, dan <strong>Sembunyikan yang ditutup</strong> menyingkirkan setiap tiket yang statusnya ditandai sebagai ditutup. Saat filter aktif, corong diberi titik dan sebuah label muncul di samping judul daftar, sehingga Anda selalu tahu bahwa Anda tidak melihat semuanya. Saat folder dikelompokkan menurut <strong>Analis</strong>, folder Anda sendiri berada di paling atas sebagai <strong>Tiket saya</strong>. Pencarian punya sakelar <strong>Sertakan tiket yang ditutup</strong> sendiri, aktif secara default, karena pencarian biasanya untuk menemukan tiket lama. Kedua pilihan ini disimpan hanya untuk Anda.',
            'row_name' => 'Setiap baris menampilkan referensi tiket lalu sebuah nama. Secara default itu adalah <strong>orang yang membuat tiket</strong>, dan tetap sama selama tiket ada. Jika Anda lebih suka melihat pengirim pesan terbaru &mdash; yang menjadi kotak surat Anda sendiri setelah Anda membalas &mdash; ubah <strong>Nama di samping nomor tiket</strong> di <strong>Pengaturan &rarr; Tampilan baris</strong>, tempat Anda juga dapat menyembunyikan nama dan menyisakan referensinya saja. Tab itu adalah pengaturan Anda sendiri: tidak mengubah apa pun bagi orang lain.',
            'tip' => 'Klik tiket mana pun di daftar untuk memuatnya di panel baca. Dari sana Anda dapat memperbarui bidang, menambahkan komentar, membalas lewat email, atau melampirkan berkas &mdash; semuanya tanpa meninggalkan kotak masuk.',
        ],
        'watch' => [
            'heading' => 'Memantau tiket',
            'body' => 'Ikuti tiket tanpa memilikinya - pemimpin tim yang mengawasi insiden besar, atau analis yang menyerahkannya. Pemantau diberi tahu tentang tiket seolah-olah itu miliknya, melalui pengaturan notifikasi mereka sendiri.',
            'how' => '<strong>Pantau</strong> di bilah alat tiket, atau klik kanan tiket di daftar dan pilih <strong>Pantau</strong>. Klik kanan pada pilihan untuk memantau semuanya. Tempat yang sama menampilkan <strong>Berhenti memantau</strong>.',
            'others' => 'Tombol <strong>Pantau</strong> menampilkan siapa yang memantau. Dengan akses tulis ke Tiket Anda dapat <strong>menambahkan rekan</strong> atau mengeluarkan seseorang; siapa pun dapat mengeluarkan dirinya sendiri.',
            'what' => '<strong>Tiket &rarr; Pengaturan &rarr; Umum &rarr; Memantau tiket</strong> memilih hal yang diberitahukan kepada pemantau - balasan, catatan, status, prioritas, penugasan ulang, peringatan dan pelanggaran SLA - semuanya kecuali administrator menghapus centang sebagian. Penugasan ulang sampai kepada pemantau sebagai "ditugaskan ulang", tidak pernah "ditugaskan kepada Anda", dan memiliki sakelarnya sendiri di preferensi masing-masing orang.',
            'note' => 'Hanya orang yang dapat melihat tiket yang dapat memantaunya, dan jika mereka tidak lagi dapat melihatnya, mereka berhenti diberi tahu. Tidak ada yang diberi tahu tentang perubahan mereka sendiri. Penggabungan memindahkan pemantau ke tiket yang bertahan.',
        ],
        // GH #272: forms on a ticket.
        'forms_on_ticket' => [
            'heading' => 'Formulir pada tiket',
            'body' => 'Lampirkan formulir dari modul Formulir ke tiket dan isi di sana - permintaan karyawan baru yang membutuhkan formulir perlengkapannya, atau insiden keamanan yang membutuhkan laporannya. Jawaban disimpan bersama tiket.',
            'switch' => '<strong>Tiket &rarr; Pengaturan &rarr; Daftar periksa &rarr; Formulir pada tiket</strong> mengaktifkannya (nonaktif sampai Anda mengaktifkannya, dan modul Formulir juga harus aktif). Tombol <strong>Formulir</strong> lalu muncul di bilah alat setiap tiket, dengan jumlah yang sudah dikirim.',
            'how' => '<strong>Formulir</strong> membuka daftar: <strong>Tambah</strong> memilih formulir (selalu versi terbarunya), <strong>Isi</strong> membukanya di jendela, <strong>Simpan draf</strong> menyimpan jawaban setengah jadi yang bisa dilanjutkan rekan, dan <strong>Koreksi</strong> mengganti kiriman sambil menyimpan yang lama di Formulir.',
            'required' => 'Setiap formulir berstatus <strong>Wajib - memblokir penutupan</strong>, <strong>Wajib - memperingatkan saat penutupan</strong> atau <strong>Opsional</strong>. Formulir yang memblokir harus dikirim sebelum tiket dapat mencapai status tertutup; yang memperingatkan akan bertanya dan mencatat siapa yang tetap menutupnya.',
            'note' => 'Mengisi formulir membutuhkan akses tulis ke Formulir. Membaca jawaban membutuhkan akses ke Formulir atau izin <strong>Membaca jawaban formulir pada tiket yang dapat Anda lihat</strong> (pengaturan peran); orang lain melihat siapa yang mengirim dan kapan, tetapi tidak isi jawabannya. Kiriman yang diandalkan tiket tidak dapat dihapus dari Formulir. Jawaban muncul di laporan kasus tiket dan di REST API.',
        ],
        'faster' => [
            'heading' => 'Bekerja lebih cepat',
            'intro' => 'Empat hal yang mengubah pagi yang sibuk menjadi terkendali: balasan tersimpan, menangani banyak tiket sekaligus, dan menempatkan percakapan di tempat yang semestinya.',
            'templates_heading' => 'Balasan siap pakai',
            'templates_body' => 'Anda terus-menerus mengirim beberapa balasan yang sama. Tulis sekali, lalu klik <strong>Templat</strong> di kiri bawah jendela balasan untuk menyisipkannya di posisi kursor &mdash; teks ditambahkan ke yang sudah Anda ketik, bukan menggantikannya. Templat berupa teks kaya dan mendukung placeholder <code>[merge_code]</code> yang sama seperti email otomatis, sehingga <code>[requester_first_name]</code> menjadi nama sebenarnya saat Anda menyisipkannya.',
            'templates_team' => '<strong>Templat tim</strong> &mdash; dibagikan kepada semua orang, diatur di Pengaturan &rarr; Templat balasan.',
            'templates_mine' => '<strong>Milik Anda sendiri</strong> &mdash; simpan draf dengan <em>Simpan draf sebagai templat</em>. Pribadi untuk Anda, dan tidak perlu izin.',
            'templates_tip' => 'Beri nama templat sesuai situasinya ("Printer offline &mdash; langkah pertama"), bukan sesuai kata-katanya. Itulah yang akan Anda cari pada pukul 9 pagi.',
            'select_heading' => 'Memilih beberapa tiket',
            'select_body' => 'Daftar tiket bekerja seperti Outlook atau File Explorer. Tanpa kotak centang.',
            'key_click' => 'Klik',
            'key_click_d' => 'pilih satu dan buka',
            'key_ctrl' => 'Ctrl+klik',
            'key_ctrl_d' => 'tambah atau hapus satu, tanpa mengubah yang lain',
            'key_shift' => 'Shift+klik',
            'key_shift_d' => 'pilih satu blok penuh dari tempat Anda terakhir mengklik',
            'key_kb' => 'Keyboard',
            'key_kb_d' => 'tombol panah untuk berpindah, Shift+panah untuk memperluas, Ctrl+panah dan Spasi untuk memilih tiket yang terpencar, Ctrl+A untuk semuanya, Escape untuk mengosongkan',
            'select_actions' => 'Dengan beberapa tiket terpilih, <strong>klik kanan salah satunya</strong> untuk mengatur status, prioritas, departemen, tipe, atau penerima tugas bagi semuanya sekaligus &mdash; atau seret seluruh pilihan ke sebuah folder. Apa yang ditampilkan layar saat beberapa tiket dipilih adalah pilihan Anda, di menu akun pada Preferensi.',
            'select_tip' => 'Mengklik kanan tiket yang <em>tidak</em> termasuk dalam pilihan Anda akan mengosongkan pilihan dan hanya menargetkan tiket itu. Ini disengaja &mdash; Anda tidak akan pernah bertindak pada sekumpulan tiket yang Anda kira sudah ditinggalkan.',
            'merge_heading' => 'Menggabungkan duplikat',
            'merge_body' => 'Dua orang melaporkan gangguan yang sama? Pilih tiketnya, klik kanan, <strong>Gabungkan</strong>. Percakapannya disatukan, dan jika Anda telah mengonfigurasi penyedia AI, FreeITSM menulis ringkasan singkat tentang apa yang diminta semua orang dan apa yang sudah dilakukan, sehingga siapa pun yang menanganinya tidak perlu membaca empat utas.',
            'merge_tip' => 'Tidak ada yang pernah dihapus. Tiket yang digabungkan tetap memiliki referensinya, tetap dapat dicari, menunjukkan ke mana tiket itu pindah &mdash; dan pelanggan yang membalas email lama tentangnya tetap sampai kepada Anda.',
            'split_heading' => 'Memisahkan tiket',
            'split_body' => 'Pekerjaan sebaliknya. Saat seseorang mengangkat hal kedua yang tidak berkaitan di tengah percakapan, klik <strong>Pisahkan</strong> pada pesan itu (atau klik kanan header pesan). Pesan itu pindah ke tiket baru, dengan pilihan membawa semua pesan yang lebih baru, dan tiket asli menyimpan penanda yang menunjukkan ke mana pesan itu pergi.',
            'split_tip' => 'Beri tiket baru subjek yang layak. Secara default subjeknya mengikuti pesan yang dipindahkan, yang biasanya berupa "RE:" dari masalah yang <em>lama</em>.',
            'undo_heading' => 'Berubah pikiran',
            'undo_body' => 'Keduanya dapat dibatalkan dari banner pada tiket. Membatalkan <strong>pemisahan</strong> ditolak setelah ada yang membalas di tiket baru, menambahkan catatan, atau mencatat waktu &mdash; Anda diberi tahu persis apa yang menghalangi. Membatalkan <strong>penggabungan</strong> mengembalikan pesan, catatan, dan waktu yang tercatat ke tiket itu dan membukanya kembali persis seperti semula, tetapi balasan yang ditulis di tiket lain sejak penggabungan tetap berada di sana.',
        ],
        'working' => [
            'heading' => 'Bekerja dengan tiket',
            'intro' => 'Setiap permintaan dukungan mengikuti siklus hidup: dibuat, dipilah, dikerjakan, dan akhirnya diselesaikan. Modul Tiket memberi Anda alat untuk mengelola setiap tahap dengan efisien, dari pencatatan awal hingga penutupan.',
            'creating_heading' => '<strong>Membuat tiket baru</strong>',
            'step1' => '<strong>Klik Baru</strong> &mdash; buka modal tiket baru dari toolbar kotak masuk. Masukkan nama dan alamat email peminta agar mereka dapat menerima pembaruan.',
            'step2' => '<strong>Atur subjek</strong> &mdash; tulis ringkasan masalah yang jelas dan singkat. Ini muncul di daftar tiket dan di setiap notifikasi email yang dikirim ke pengguna akhir.',
            'step3' => '<strong>Pilih departemen, tipe, dan prioritas</strong> &mdash; pilih departemen yang sesuai, tipe tiket (mis. Insiden, Permintaan Layanan), dan tingkat prioritas. Bidang-bidang ini menentukan pengatur waktu SLA dan aturan perutean.',
            'step4' => '<strong>Tambahkan deskripsi</strong> &mdash; berikan detail lengkap masalah menggunakan editor teks kaya. Sertakan langkah untuk mereproduksi, pesan kesalahan, dan konteks relevan yang dibutuhkan analis yang menyelesaikannya.',
            'step5' => '<strong>Simpan</strong> &mdash; tiket dibuat dengan nomor referensi unik dan muncul di folder yang sesuai. Jam SLA langsung berjalan berdasarkan prioritas.',
            'editing_heading' => '<strong>Mengedit dan mengelola tiket</strong>',
            'editing_body' => 'Setelah tiket ada, Anda dapat memperbarui bidang mana pun dari panel baca. Bidang utamanya meliputi:',
            'card_status_title' => 'Status',
            'card_status_body' => 'Lacak siklus hidup tiket: Baru, Terbuka, Sedang Dikerjakan, Tertunda, Teratasi, Ditutup',
            'card_priority_title' => 'Prioritas',
            'card_priority_body' => 'Atur urgensi dan dampak: Kritis, Tinggi, Sedang, Rendah. Setiap tingkat memiliki target SLA sendiri',
            'card_category_title' => 'Kategori',
            'card_category_body' => 'Klasifikasikan jenis masalah: Perangkat Keras, Perangkat Lunak, Jaringan, Akses, Umum. Berguna untuk pelaporan',
            'card_analyst_title' => 'Analis yang ditugaskan',
            'card_analyst_body' => 'Orang yang bertanggung jawab menyelesaikan tiket. Penugasan ulang dicatat di jejak aktivitas',
            'card_enduser_title' => 'Pengguna akhir',
            'card_enduser_body' => 'Orang yang mengajukan permintaan. Cari berdasarkan nama atau email untuk menautkan ke data pengguna yang sudah ada',
            'card_dept_title' => 'Departemen',
            'card_dept_body' => 'Arahkan tiket ke tim yang tepat. Departemen menentukan pengelompokan folder dan filter dasbor',
            'flow_new' => 'Baru',
            'flow_in_progress' => 'Sedang Dikerjakan',
            'flow_resolved' => 'Teratasi',
            'flow_closed' => 'Ditutup',
            'triage_heading' => '<strong>Memilah dengan seret dan lepas</strong>',
            'triage_body' => 'Anda tidak perlu membuka tiket untuk memilahnya. Seret baris mana pun dari daftar tiket ke sebuah folder untuk memperbarui bidang dalam satu gerakan:',
            'triage_dept' => '<strong>Tampilan Departemen</strong> &mdash; lepas di folder departemen untuk menugaskan ulang, lepas di subfolder status di bawah departemen untuk memperbarui keduanya sekaligus, lepas di <strong>Belum ditugaskan</strong> untuk mengosongkan departemen.',
            'triage_analyst' => '<strong>Tampilan Analis</strong> &mdash; lepas di folder seorang analis untuk menugaskan analis itu sebagai pemilik (mengatur <code>assigned_analyst_id</code> dan <code>owner_id</code> sekaligus agar bidang Pemilik di panel baca tetap sinkron), lepas di subfolder status untuk memperbarui keduanya, lepas di <strong>Belum ditugaskan</strong> untuk mengosongkan penerima tugas.',
            'triage_spring' => '<strong>Folder yang terbuka sendiri</strong> &mdash; arahkan kursor ke folder yang tertutup saat menyeret dan folder itu terbuka otomatis (gaya Outlook) sehingga status bersarang apa pun dapat dijangkau tanpa harus melepas terlebih dahulu.',
            'fullscreen_heading' => '<strong>Tampilan layar penuh</strong>',
            'fullscreen_body' => 'Saat Anda perlu fokus pada satu tiket &mdash; percakapan panjang, perubahan rumit, menyusun balasan yang detail &mdash; beralihlah ke tampilan layar penuh. Daftar folder dan daftar tiket menghilang, percakapan memenuhi lebar yang tersedia, dan properti (Departemen, Tipe, Status, Asal, Perbaikan Pertama Kali, Pelatihan TI, Pemilik) pindah ke bilah samping vertikal di kanan.',
            'fullscreen_max' => '<strong>Ikon maksimalkan</strong> &mdash; ikon kecil di ujung kanan baris subjek tiket. Klik untuk masuk ke layar penuh; klik lagi untuk kembali ke tata letak 3 panel.',
            'fullscreen_dbl' => '<strong>Klik ganda pada baris</strong> &mdash; klik ganda tiket mana pun di daftar untuk membukanya langsung dalam layar penuh, gestur ala Outlook "buka yang satu ini sungguh-sungguh".',
            'fullscreen_sticks' => '<strong>Bertahan di antara pilihan</strong> &mdash; setelah Anda berada di layar penuh, berpindah ke tiket berikutnya tetap membuat Anda di sana. Memuat ulang halaman (F5) tanpa tiket terpilih akan kembali ke tata letak 3 kolom default, sehingga Anda tidak bisa terjebak dengan daftar folder tersembunyi.',
            'fullscreen_back' => '<strong>Kembali</strong> &mdash; bilah di atas tiket menampilkan referensinya dan tombol <strong>Kembali</strong>, yang mengembalikan Anda ke daftar persis seperti saat Anda tinggalkan, dengan keyboard kembali ke daftar - sehingga tombol panah berpindah antar tiket dan Enter langsung membuka tiket berikutnya. <strong>Escape</strong> melakukan hal yang sama, setelah jendela atau menu yang terbuka di atas tiket ditutup.',
            'fullscreen_keys' => '<strong>Tombol menggulir tiket</strong> &mdash; dalam layar penuh, tombol panah, Page Up / Page Down, dan Spasi menggulir percakapan, bukan daftar tiket yang tersembunyi. Di jendela gambar atau PDF, tombol tersebut menggulir jendela itu. Di tampilan tiga panel normal, klik di tiket dan tombol juga menggulirnya; klik daftar untuk kembali berpindah antar tiket.',
            'viewer_heading' => '<strong>Gambar dan PDF terbuka di atas tiket</strong>',
            'viewer_body' => 'Klik gambar atau PDF yang dilampirkan pada catatan, atau yang ada di daftar <strong>Lampiran</strong> tiket (gambar mini atau barisnya), dan file terbuka di jendela di atas tiket &mdash; penampil yang sama dengan modul Berkas. Tiket tetap persis di tempatnya di bawah.',
            'viewer_window' => '<strong>Pindahkan dan ubah ukurannya</strong> &mdash; seret bilah judul untuk memindahkan jendela dan tepi atau sudut mana pun untuk mengubah ukurannya; klik dua kali bilah judul, atau seret ke bagian atas layar, untuk memenuhi layar. Gambar atau PDF menyesuaikan ulang saat ukuran jendela berubah, sampai Anda memperbesar atau memperkecil sendiri &mdash; <strong>Sesuaikan</strong> mengembalikannya. Buka beberapa dan jendela-jendela itu berdampingan.',
            'viewer_close' => '<strong>Tutup</strong> &mdash; &times; di bilah judulnya, atau <strong>Escape</strong> (yang menutup jendela paling depan). <strong>Unduh</strong> menyimpan berkas. Di ponsel, berkas terbuka layar penuh dengan tombol Kembali.',
            'viewer_other' => '<strong>Berkas lain</strong> &mdash; dokumen Word, spreadsheet, dan yang lainnya tetap diunduh atau dibuka di tab baru, seperti sebelumnya. Untuk membuka gambar atau PDF catatan di tab baru, Ctrl-klik.',
            'paste_heading' => '<strong>Tempel tangkapan layar ke catatan</strong>',
            'paste_body' => 'Salin tangkapan layar, klik kotak <strong>Tambah catatan</strong> dan tekan <strong>Ctrl+V</strong>. Gambar masuk di tempat kursor berada, dengan teks Anda sebelum dan sesudahnya, dan tetap di tempat itu setelah catatan disimpan. Klik untuk membukanya di penampil. <strong>Backspace</strong> menghapusnya sebelum Anda menyimpan.',
            'paste_shared' => '<strong>Catatan bersama membagikan gambarnya</strong> &mdash; peminta melihatnya di portal, di tempatnya. Pada catatan internal, gambar sama privatnya dengan catatannya.',
            'paste_save' => '<strong>Tidak ada yang disimpan sampai Anda menekan Simpan</strong> &mdash; tutup kotak dan gambar ikut hilang. Jika gambar ditolak, catatan juga tidak disimpan, alasannya ditampilkan, dan teks Anda tetap di dalam kotak.',
            'paste_text' => '<strong>Teks tetap teks</strong> &mdash; menempel dari Word, halaman web, atau Excel memasukkan kata-katanya tanpa pemformatan. Tombol <strong>Lampirkan</strong> tetap berfungsi untuk berkas lain.',
            'rightclick_heading' => '<strong>Klik kanan untuk tindakan cepat</strong>',
            'rightclick_body' => 'Klik kanan tiket mana pun di daftar untuk membuka menu konteks. Menu menampilkan referensi tiket di bagian atas agar Anda tahu apa yang sedang Anda tangani, dan setiap tindakan bekerja pada tiket yang diklik kanan <em>tanpa</em> mengubah apa yang sedang terbuka di panel baca &mdash; berguna saat Anda membaca tiket A dan perlu memilah tiket B tanpa kehilangan posisi.',
            'rightclick_status' => '<strong>Atur status &rarr;</strong> &mdash; submenu flyout yang mencantumkan setiap status aktif dengan swatch warnanya. Tanda centang muncul di samping nilai saat ini jika Anda mengklik kanan tiket yang sedang terbuka. Pilihan langsung memperbarui tiket, menulis entri jejak audit, menyegarkan jumlah folder, dan menyinkronkan dropdown Status di panel baca jika berlaku.',
            'rightclick_priority' => '<strong>Atur prioritas &rarr;</strong> &mdash; pola flyout yang sama, bersumber dari daftar prioritas aktif dengan warna masing-masing sebagai swatch. Baris pertama adalah opsi <em>(tanpa prioritas)</em> untuk mengosongkan penetapan (prioritas boleh kosong).',
            'rightclick_assign' => '<strong>Tugaskan ke &rarr;</strong> &mdash; submenu yang mencantumkan setiap analis yang dimuat dengan chip inisial abu-abu, ditambah baris <em>(belum ditugaskan)</em> di atas untuk mengosongkan. Pilihan mengatur <code>assigned_analyst_id</code> DAN <code>owner_id</code> sekaligus agar bidang Pemilik di panel baca tetap sinkron.',
            'rightclick_cmdb' => '<strong>Tautkan objek CMDB&hellip;</strong> &mdash; membuka pemilih dengan pencarian saat mengetik. Klik hasil untuk menautkannya, lalu lanjutkan memilih &mdash; kolom input dikosongkan dan difokuskan kembali untuk yang berikutnya, dan log "Baru ditautkan" di dalam modal menampilkan daftar konfirmasi centang hijau Anda.',
            'rightclick_time' => '<strong>Catat waktu&hellip;</strong> &mdash; membuka modal dengan menit + pemilih tanggal-waktu (default "sekarang" sehingga Anda juga dapat mencatat mundur) + kotak catatan opsional.',
            'rightclick_phone' => '<strong>Di ponsel</strong>, tekan dan tahan tiket selama setengah detik untuk membuka menu yang sama sebagai panel layar penuh. Pilihan dengan opsi lebih lanjut &mdash; Atur status, Atur prioritas, Tugaskan ke &mdash; bergeser ke opsi tersebut, dengan <strong>Kembali</strong> untuk kembali.',
            'rightclick_tip' => 'Jika tiket yang Anda tangani lewat menu konteks kebetulan sama dengan yang terbuka di panel baca, bagian terkait di sana (dropdown Status / Prioritas, objek CMDB, entri waktu) disegarkan otomatis saat modal ditutup sehingga UI tetap sinkron.',
            'time_heading' => '<strong>Mencatat waktu</strong>',
            'time_body' => 'Waktu yang dihabiskan pada tiket dicatat di bagian khusus <strong>Entri Waktu</strong> pada panel baca, di antara panel objek CMDB yang tertaut dan panel Catatan. Header menampilkan total berjalan (mis. "Total 2h 30m"), dan setiap entri di bawahnya menampilkan waktu yang dihabiskan, analis, tanggal, dan catatan yang Anda tambahkan.',
            'time_step1' => '<strong>Formulir sebaris</strong> &mdash; ketik menit yang dihabiskan ke input numerik, deskripsi singkat opsional ke input catatan, dan klik <strong>Tambah</strong>. Entri baru langsung muncul di bagian atas daftar dengan nama Anda dan stempel waktu saat ini.',
            'time_step2' => '<strong>Catat mundur lewat klik kanan</strong> &mdash; jika Anda perlu mencatat waktu yang lupa dicatat sebelumnya, klik kanan tiket di daftar dan pilih <strong>Catat waktu&hellip;</strong>. Modal memuat pemilih tanggal-waktu agar Anda dapat memberi stempel waktu pengerjaan yang sebenarnya pada entri.',
            'time_step3' => '<strong>Hapus entri Anda sendiri</strong> &mdash; tombol &times; kecil muncul di samping entri yang Anda catat. Klik (dan konfirmasi) untuk penghapusan lunak &mdash; barisnya tetap ada di database dengan <code>is_active = 0</code> untuk audit, tetapi hilang dari daftar. Anda tidak dapat menghapus entri analis lain.',
            'time_tip1' => 'Waktu disimpan sebagai menit biasa (45 menit, 90 menit, dst.) dan ditampilkan sebagai <code>45m</code> atau <code>1h 30m</code> di UI &mdash; cukup rinci untuk perbaikan singkat, tanpa repotnya pembulatan jam desimal.',
            'time_tip2' => 'Setiap perubahan bidang dicatat di jejak aktivitas tiket. Anda selalu dapat melihat siapa mengubah apa dan kapan, yang penting untuk kepatuhan audit dan serah terima antar analis.',
        ],
        'comments' => [
            'heading' => 'Komentar &amp; lampiran',
            'intro' => 'Jejak aktivitas adalah inti dari setiap tiket. Jejak ini mencatat setiap tindakan &mdash; komentar, perubahan bidang, email terkirim, dan berkas terlampir &mdash; dalam lini masa kronologis yang menceritakan seluruh kisah sebuah permintaan dukungan.',
            'adding_heading' => '<strong>Menambahkan komentar</strong>',
            'step1' => '<strong>Buka tiket</strong> &mdash; klik tiket mana pun di kotak masuk untuk memuat panel bacanya. Gulir ke bawah untuk melihat jejak aktivitas lengkap dan kotak komentar di bagian bawah.',
            'step2' => '<strong>Tulis catatan Anda</strong> &mdash; gunakan tombol Tambah Catatan untuk membuka editor komentar. Catatan bersifat internal secara default, hanya terlihat oleh analis di service desk.',
            'step3' => '<strong>Balas atau teruskan lewat email</strong> &mdash; gunakan tindakan Balas atau Teruskan untuk mengirim pesan ke pengguna akhir atau pihak ketiga. Email dicatat di jejak aktivitas bersama isi pesan keluarnya.',
            'files_heading' => '<strong>Lampiran berkas</strong>',
            'files_body' => 'Lampirkan tangkapan layar, log, dokumen, atau berkas pendukung apa pun langsung ke tiket. Berkas dapat diseret ke area lampiran atau dipilih menggunakan penjelajah berkas. Lampiran disimpan di server dan ditautkan ke jejak aktivitas tiket sehingga tidak ada yang hilang.',
            'audit_heading' => '<strong>Pencatatan audit</strong>',
            'export_heading' => '<strong>Laporan kasus</strong>',
            'export_body' => 'Untuk tinjauan atau auditor, <strong>Ekspor</strong> di bilah alat tiket mengubah tiket dan tugasnya menjadi satu laporan yang dapat dicetak - lihat <a href="#case-reports">Laporan kasus</a>.',
            'audit_body' => 'Jejak aktivitas mencatat setiap tindakan secara otomatis tanpa campur tangan analis. Saat prioritas diubah dari Sedang ke Tinggi, nilai lama dan barunya tersimpan. Saat tiket ditugaskan ulang, analis sebelumnya dan yang baru dicatat. Ini menghasilkan riwayat lengkap yang tidak dapat dimanipulasi, yang memenuhi persyaratan audit ITIL dan membantu manajer memahami bagaimana tiket ditangani.',
            'tip' => 'Saat membalas lewat email, Anda dapat menambahkan penerima Cc dan melampirkan berkas dalam tindakan yang sama. Seluruh percakapan email dirangkai ke dalam jejak aktivitas tiket, menjaga semua komunikasi di satu tempat.',
        ],
        'ai' => [
            'heading' => 'Alat AI',
            'intro' => 'Dua fitur berbasis Claude ada di dalam alur kerja tiket: <strong>Rapikan Balasan</strong> menulis ulang draf kasar menjadi email yang diformat dengan baik, dan <strong>Tanya AI</strong> mencari di basis pengetahuan dengan bahasa alami menggunakan konteks tiket.',
            'cleanup_heading' => '<strong>Rapikan Balasan &mdash; tombol ✨ di editor balasan</strong>',
            'cleanup_body' => 'Ketik draf kasar singkat ke dalam balasan (atau sekadar poin-poin seperti *"perlu restart layanan cetak, ambil tangkapan layar untuk mereka"*) dan klik tombol <strong>✨ Rapikan</strong>. Claude menulis ulangnya sebagai email yang diformat dengan baik &mdash; menambahkan salam <em>Yth. [nama],</em> dari peminta, memperbaiki tata bahasa, menerapkan nada yang dikonfigurasi, dan menutup dengan <em>Hormat kami,</em>. Prompt dikunci sehingga TIDAK akan mengarang detail teknis, mengada-adakan permintaan maaf, atau menambah isi melebihi yang Anda tulis.',
            'cleanup_streams' => '<strong>Tayang langsung</strong> &mdash; hasil tulis ulang muncul di editor saat Claude membuatnya (tanpa menunggu di depan ikon pemuatan).',
            'cleanup_undo' => '<strong>Tautan Urungkan selama 30 detik</strong> &mdash; kalau-kalau Claude merusak hasilnya, tautan <em>Urungkan</em> kecil muncul di bawah editor selama 30 detik setelah penulisan ulang selesai, mengembalikan draf asli.',
            'cleanup_tone' => '<strong>Per nada</strong> &mdash; tiga preset nada yang dapat dikonfigurasi di <strong>Pengaturan &rarr; Rapikan Balasan</strong>: <em>Ramah</em> (default), <em>Formal</em>, <em>Ringkas</em>. Pilih yang sesuai dengan gaya tim Anda.',
            'cleanup_key' => '<strong>API key sendiri</strong> &mdash; key Anthropic terpisah dari fitur AI RFP / Pengetahuan / Alur Kerja sehingga penggunaannya tampil sebagai baris tersendiri di dasbor penagihan Anthropic. Dikonfigurasi di <strong>Pengaturan &rarr; Rapikan Balasan</strong>.',
            'cleanup_tip' => 'Rapikan paling cocok untuk balasan rutin bergaya "Saya sudah mencoba ini, tolong coba X". Untuk pesan yang panjang dan penuh nuansa, sebaiknya Anda tulis sendiri &mdash; AI hebat dalam struktur tetapi tidak mengenal lingkungan spesifik Anda.',
            'ask_heading' => '<strong>Tanya AI &mdash; tombol 🤖 di toolbar tiket</strong>',
            'ask_body' => 'Klik tombol <strong>Tanya AI</strong> (🤖) di toolbar tiket untuk membuka panel obrolan geser-masuk yang mengetahui subjek, isi, dan konteks panel baca tiket yang terbuka. Ajukan pertanyaan seperti *"apakah kita pernah melihat ini sebelumnya?"* atau *"apa perbaikan yang biasa untuk kesalahan ini?"* dan AI mencari di basis <a href="../knowledge/" style="color:#0078d4;">Pengetahuan</a> secara semantik (lewat Claude + embedding OpenAI) dan membalas dengan artikel yang relevan, lengkap dengan tautan langsung untuk membukanya.',
            'ask_context' => '<strong>Sadar konteks</strong> &mdash; panel tahu tiket mana yang sedang Anda lihat, sehingga Anda bisa mengajukan pertanyaan umum dan AI menemukan konteks yang relevan.',
            'ask_linked' => '<strong>Artikel tertaut</strong> &mdash; saran dapat diklik dan membuka artikel pengetahuan yang cocok di tab baru.',
            'ask_shared' => '<strong>Dibagikan dengan modul Pengetahuan</strong> &mdash; AI memakai key + model yang sama dengan pencarian AI Pengetahuan, sehingga mengonfigurasinya sekali memberi Anda keduanya. Lihat bantuan modul Pengetahuan untuk detail penyiapan.',
        ],
        'csat' => [
            'heading' => 'Survei kepuasan pelanggan (CSAT)',
            'intro' => 'Kirim survei kepuasan 1&ndash;5 lewat email kepada peminta saat tiket diselesaikan, tangkap responsnya di halaman tujuan tanpa login, dan lacak tren per analis di halaman analitik khusus.',
            'modes_heading' => '<strong>Dua mode pemicu &mdash; pilih satu</strong>',
            'mode_auto' => '<strong>Otomatis saat ditutup</strong> &mdash; survei diantrekan otomatis saat tiket beralih ke status ditutup apa pun. Analis tidak perlu melakukan apa-apa &mdash; penyelesaian yang memicu survei.',
            'mode_manual' => '<strong>Hanya manual</strong> &mdash; analis mengklik tombol ⭐ <strong>Umpan balik</strong> di toolbar tiket saat ingin bertanya. Berguna jika Anda lebih suka memutuskan per tiket apakah akan meminta umpan balik.',
            'switch_note' => 'Tidak memakai CSAT sama sekali? Nonaktifkan di <strong>Sistem &rarr; Modul &rarr; Ketersediaan &rarr; Fitur tiket</strong> dan CSAT hilang: tidak ada survei, tidak ada halaman CSAT, tidak ada tombol Minta masukan, dan tautan survei lama menyatakan masukan tidak lagi dikumpulkan. Tidak ada yang dihapus.',
            'mode_off' => '<strong>Nonaktif</strong> &mdash; fitur dinonaktifkan; tidak ada email survei yang dikirim.',
            'modes_choose' => 'Pilih di <strong>Tiket &rarr; Pengaturan &rarr; CSAT</strong>. Tombol manual tetap berfungsi pada mode <em>otomatis</em> &mdash; analis dapat meminta ulang umpan balik pada tiket yang sudah disurvei jika perlu.',
            'template_heading' => '<strong>Templat email</strong>',
            'template_body' => 'Isi email survei berasal dari tab <strong>Templat email</strong> yang sudah ada &mdash; buat templat dengan peristiwa <strong>Survei CSAT</strong> (peristiwa baru di samping <em>Tiket ditugaskan</em> / <em>Tiket ditutup</em>) dan sematkan kode gabungan <code>[csat_link]</code> di mana pun Anda ingin URL penilaian muncul. Kode gabungan standar (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) tersedia seperti biasa.',
            'template_tip' => 'Jika tidak ada templat CSAT aktif, tombol <em>Umpan balik</em> menolak dengan pesan kesalahan yang jelas dan pemicu otomatis dilewati tanpa suara &mdash; Anda tidak akan pernah menghasilkan tautan survei yang mati.',
            'survey_heading' => '<strong>Halaman survei</strong>',
            'survey_body' => 'Peminta mengklik tautan di email dan masuk ke halaman tanpa login dengan pemilih 1&ndash;5 plus kotak komentar opsional. Dua gaya visual dapat dikonfigurasi di <strong>Pengaturan &rarr; CSAT</strong>:',
            'survey_stars' => '<strong>Bintang</strong> &mdash; perilaku klasik terisi saat disorot. Menyorot bintang #3 mengisi #1+#2+#3 dengan warna emas. Klik untuk mengunci.',
            'survey_emojis' => '<strong>Emoji</strong> &mdash; 5 wajah 😡 🙁 😐 🙂 😀 mulai dalam skala abu-abu dengan opasitas 40%; yang disorot atau dipilih kembali ke warna penuh pada skala 1,25&times;. Klik untuk mengunci.',
            'survey_store' => 'Kedua mode menyimpan angka 1&ndash;5 yang sama sehingga dasbor dan rata-rata bekerja identik apa pun gaya yang dipakai. URL survei hanya berlaku sekali &mdash; setelah pengguna mengirim, tautan yang sama menolak pengiriman ulang.',
            'chat_heading' => '<strong>Bertanya kepada pelanggan chat di chat mereka</strong>',
            'chat_body' => 'Dengan <strong>Tanya pelanggan chat di chat mereka</strong> dicentang, pelanggan yang menulis lewat WhatsApp, Telegram, Slack, Microsoft Teams, atau Mattermost ditanyai di chat itu, bukan lewat email &mdash; lima tombol di Telegram, Teams, dan Mattermost, &ldquo;balas dengan satu angka&rdquo; di tempat lain. Jawaban mereka masuk ke hasil yang sama dengan survei lewat email.',
            'chat_rules' => 'WhatsApp hanya ditanyai selama jendela balasan 24 jamnya terbuka; di luar itu, atau jika pesan chat tidak dapat dikirim, survei email dipakai sebagai gantinya. Sebuah angka dihitung sebagai penilaian hanya jika langsung setelah pertanyaan &mdash; di chat yang sama, dalam seminggu, dan sebelum pelanggan menulis hal lain &mdash; sehingga &ldquo;3&rdquo; sebagai jawaban atas pertanyaan analis tetap berupa pesan. Nonaktif setelah pembaruan; aktif untuk instalasi baru.',
            'analytics_heading' => '<strong>Halaman analitik</strong>',
            'analytics_body' => 'Klik tombol navigasi ⭐ <strong>CSAT</strong> (di antara Jadwal dan Pengaturan) untuk membuka dasbor analitik di <code>tickets/csat/</code>. Rentang yang dapat dipilih: 7 / 30 / 90 / 365 hari.',
            'card_kpi_title' => 'Kartu KPI',
            'card_kpi_body' => 'Penilaian rata-rata (dari 5), jumlah respons, tingkat respons (dijawab ÷ dikirim)',
            'card_dist_title' => 'Distribusi skor',
            'card_dist_body' => 'Grafik batang penilaian 1–5 yang menampilkan jumlah dan persentase persisnya',
            'card_leader_title' => 'Papan peringkat per analis',
            'card_leader_body' => 'Penilaian rata-rata + jumlah respons per analis, diurutkan menurut rata-rata menurun. Gunakan untuk percakapan pengembangan',
            'card_recent_title' => 'Respons terbaru',
            'card_recent_body' => 'Penilaian yang terbaru lebih dulu, 25 per halaman, beserta komentar teks bebas dan pelanggan yang memberikannya, ditautkan kembali ke tiket sumbernya',
            'analytics_filters' => 'Persempit halaman dengan filter di bawah judul: rentang tanggal <strong>Dari / Sampai</strong> (sebagai ganti tombol hari), rentang <strong>Penilaian</strong> (Positif 4-5, Netral 3, Negatif 1-2), sebuah <strong>Analis</strong>, dan sebuah <strong>Pelanggan</strong>. Analis dan pelanggan mempersempit setiap angka di halaman; rentang penilaian hanya mempersempit daftar respons, sehingga rata-ratanya tetap bermakna. Di ponsel, filter berada di balik tombol <strong>Filter</strong> di bagian bawah layar. Halaman yang difilter dapat diberi bookmark.',
            'analytics_company' => 'Setiap angka mengikuti <strong>pengalih perusahaan</strong> di header: perusahaan yang Anda pilih, atau semua perusahaan yang dapat Anda lihat di bawah <strong>Semua perusahaan</strong>.',
            'analytics_tip' => 'Atribusi per analis tetap ada meski tiket ditugaskan ulang karena ID analis ditangkap ke baris survei saat pengiriman, bukan dicari secara langsung. Jika tiket dioper ke sana kemari sebelum ditutup, analis yang benar-benar menutupnya memiliki penilaiannya.',
            'one_heading' => '<strong>Satu survei per tiket</strong>',
            'one_body' => 'Jika <em>Satu survei per tiket</em> aktif (default), tiket yang dibuka kembali lalu ditutup hanya mendapat survei lagi saat analis memicunya secara manual &mdash; mencegah spam survei pada tiket bermasalah yang terus berputar. Nonaktifkan jika Anda ingin setiap penutupan memicu survei baru.',
        ],
        'users' => [
            'heading' => 'Manajemen pengguna',
            'intro' => 'Tombol navigasi <strong>Pengguna</strong> membuka <code>tickets/users.php</code> &mdash; direktori semua pengguna akhir (orang yang mengajukan tiket, bukan analis) beserta riwayat tiket masing-masing.',
            'p_intro' => 'Pengguna masuk ke sistem melalui empat cara reaktif &mdash; pendaftaran mandiri di portal, email masuk dari pengirim baru, pemeriksa kotak surat, atau mesin alur kerja yang membuatnya dari tiket yang terpicu. Itu mencakup sebagian besar kasus, tetapi halaman Pengguna juga memungkinkan Anda <strong>membuat pengguna lebih dulu</strong> (mis. karyawan baru yang sebentar lagi membutuhkan akses) serta <strong>mengedit</strong> atau <strong>menghapus</strong> baris yang sudah ada.',
            'add_heading' => '<strong>Tambah pengguna</strong>',
            'add_body' => 'Tombol <strong>Tambah</strong> di header daftar pengguna membuka editor orang. Editor ini sama dengan yang dibuka oleh <strong>Aset &rarr; Pengguna</strong>, sehingga orang ditambahkan dan diubah dengan cara yang sama di layar mana pun:',
            'add_email' => '<strong>Email</strong> &mdash; opsional, karena orang yang masuk melalui direktori mungkin tidak punya kotak surat; mereka ditemukan lewat nama masuknya. Isi alamat email atau nama tampilan. Alamat harus unik dan tidak boleh milik seorang analis.',
            'add_names' => '<strong>Nama tampilan / nama panggilan</strong> &mdash; opsional. Nama panggilan adalah sebutan yang dilihat pengguna saat disapa di email (mis. <em>"Ed"</em> alih-alih <em>"Ed Mozley"</em>).',
            'add_password' => '<strong>Kata sandi</strong> &mdash; opsional. Jika dikosongkan, akun dibuat <em>tanpa kata sandi</em> &mdash; persis sama dengan keadaan awal pengguna dari tiket masuk. Pengguna kemudian dapat mengklaim akun itu lewat alur pendaftaran portal layanan mandiri dengan mengatur kata sandinya sendiri.',
            'add_details' => '<strong>Jabatan, departemen, kantor, telepon, ponsel, ID karyawan, dan manajer</strong> &mdash; semuanya opsional, dan semuanya menggambarkan <em>orangnya</em>, bukan loginnya. Layak diisi: <strong>kantor</strong> memberi tahu di lokasi mana seseorang berada sebelum Anda mencarinya, <strong>manajer</strong> mencatat garis pelaporan (ketik sebagian nama untuk menemukannya), dan <strong>ID karyawan</strong> adalah kunci penghubung saat Anda mencocokkan dengan sistem penggajian yang tidak mengenal alamat email. Jika Anda mengimpor dari direktori, semuanya sudah terisi. Buku alamat CardDAV mengisi semuanya kecuali ID karyawan dan manajer, karena kartu kontak tidak punya tempat untuk menyimpannya.',
            'managed_heading' => '<strong>Orang yang dikelola di tempat lain</strong>',
            'source_body' => '<strong>Asal seseorang</strong> disebutkan di detailnya (<em>Detail dari: Contoso AD - directory</em>), dan filter <strong>Sumber</strong> di bawah kotak pencarian hanya menampilkan orang dari satu direktori atau buku alamat, atau hanya yang ditambahkan di FreeITSM, dengan jumlah di sebelah masing-masing. Filter ini muncul begitu ada orang yang terhubung ke suatu sumber.',
            'add_book_body' => '<strong>Tambahkan ke buku alamat.</strong> Orang yang mengirim email ada di sini tetapi tidak ada di buku alamat mana pun. Jika administrator mengaktifkan <em>Izinkan analis menambahkan orang ke buku alamat ini</em> (Sistem &rarr; Autentikasi, pada buku alamat), orang itu mendapat tombol <strong>Tambahkan ke buku alamat</strong> di samping Edit. Tombol ini bertanya dulu, menampilkan apa yang akan masuk ke kartu, lalu membuat kontaknya dan menautkannya &mdash; orang yang sama, bukan salinan. Ini tidak akan menambahkan orang yang alamat emailnya sudah ada di buku (jalankan impor sebagai gantinya), dan memastikan impor berikutnya mengambil kontak baru itu, atau kartunya ditarik kembali.',
            'managed_body' => 'Jika seseorang diimpor &mdash; dari LDAP atau Active Directory, atau dari buku alamat CardDAV &mdash; detail yang dimiliki sumber itu bersifat <strong>hanya-baca</strong> dan modal menampilkannya dalam warna abu-abu. Asal datanya adalah sumber kebenaran, dan impor berikutnya akan menimpa apa pun yang diketik di sini, sehingga penyimpanan ditolak sepenuhnya alih-alih diterima lalu diam-diam dikembalikan sejam kemudian. <strong>Detail mana</strong> yang terkunci bergantung pada sumbernya: direktori memiliki ketujuhnya, sedangkan buku alamat memiliki lima &mdash; buku alamat tidak punya tempat untuk nomor karyawan atau garis pelaporan, jadi keduanya tetap Anda isi sendiri. Dan jika buku alamat mengaktifkan <em>tulis perubahan kembali</em>, tidak ada yang terkunci: apa yang Anda ketik dikirim ke kartu kontak, jadi tidak ada yang akan dikembalikan oleh impor berikutnya. Semua hal lain pada catatan, termasuk perusahaan dan kata sandi, selalu dapat diedit.',
            'edit_heading' => '<strong>Edit pengguna</strong>',
            'edit_body' => 'Pilih pengguna dari daftar, lalu klik <strong>Edit</strong> di header detail. Editornya sama, sudah terisi. Menyimpan tanpa kata sandi membiarkan hash yang ada tidak berubah; mengisinya akan meresetnya. Jika manajernya adalah seseorang di perusahaan yang tidak dapat Anda lihat, kotak Manajer menyatakannya dan manajer tetap seperti semula kecuali Anda memilih orang lain.',
            'signin_body' => '<strong>Masuk dengan</strong> menunjukkan penyedia single sign-on mana yang tertaut ke seseorang. <strong>Putuskan tautan</strong> di sampingnya, setelah konfirmasi, menghapus tautan itu sehingga login berikutnya dimulai dari awal &mdash; untuk orang yang pindah ke penyedia lain, atau tertaut ke akun yang salah. Opsi ini tidak ditawarkan untuk orang yang dikelola sinkronisasi direktori, karena akan langsung ditautkan lagi.',
            'company_body' => '<strong>Perusahaan</strong> muncul jika Anda memiliki lebih dari satu. Untuk orang baru, jika dikosongkan perusahaan ditentukan dari alamat emailnya; untuk orang yang sudah ada, kosong berarti tanpa perusahaan, dan tiketnya masuk ke triase.',
            'managers_heading' => '<strong>Manajer</strong>',
            'managers_body' => 'Seseorang dapat dijadikan <strong>manajer</strong> di portal layanan mandiri: mereka mendapat tab <strong>Tiket tim</strong> yang mencantumkan tiket orang-orang yang mereka kelola. Fitur ini nonaktif sampai administrator mengaktifkannya di <strong>Sistem &rarr; Manajer</strong>, yang juga menentukan apakah manajer boleh membalas atau menutup tiket tersebut, dan apa yang mereka lihat dari tiket rahasia (tidak ada, secara default).',
            'managers_sources' => 'Seseorang menjadi manajer dengan dua cara, keduanya sekaligus: mereka adalah <strong>Manajer</strong> pada catatan orang lain (manual, atau dari direktori Anda), dan mereka memiliki <strong>garis manajemen</strong> yang disiapkan untuk mereka. Klik <strong>Akses manajer</strong> di samping Edit untuk membuka halaman layar penuh bagi orang itu, tempat Anda dapat memberi mereka semua orang, orang tertentu, grup orang, departemen, atau seluruh garis pelaporan mereka, dan <strong>mengecualikan</strong> orang &mdash; pengecualian selalu menang, termasuk atas kolom Manajer. Halaman ini menampilkan berapa banyak orang yang dapat mereka lihat dan mendaftarkannya, dihitung seolah-olah manajer sudah diaktifkan, sehingga Anda dapat memeriksa sebelum mengaktifkan. Klik siapa saja dalam daftar itu untuk melihat <strong>alasan</strong> manajer dapat melihat mereka, dan cara menghentikannya.',
            'managers_rules' => 'Manajer hanya melihat orang di perusahaannya sendiri, tidak pernah dirinya sendiri, dan tidak melihat siapa pun lagi setelah mereka keluar. Departemen dicocokkan berdasarkan nama yang diketik pada setiap orang, jadi departemen yang diganti namanya tidak lagi cocok &mdash; halaman ini, dan Sistem &rarr; Manajer, memperingatkan tentang garis departemen yang tidak cocok dengan siapa pun. Secara default hanya administrator yang dapat mengubah garis manajemen; Sistem &rarr; Manajer dapat membukanya bagi siapa saja yang dapat mengedit orang.',
            'delete_heading' => '<strong>Hapus pengguna</strong>',
            'delete_body' => 'Tombol <strong>Hapus</strong> bersifat <strong>aman terhadap FK</strong>: tombol ini menolak jika pengguna adalah peminta pada tiket mana pun atau memiliki baris di <code>users_assets</code>, dan mengembalikan pesan yang jelas <em>"Tidak dapat menghapus: pengguna ini adalah peminta pada N tiket. Tugaskan ulang atau tutup tiket tersebut terlebih dahulu."</em> Riwayat audit tidak akan pernah rusak diam-diam.',
            'tip' => 'Semua kolom modal menonaktifkan isi otomatis browser (termasuk <code>autocomplete="new-password"</code> pada kolom kata sandi) agar kredensial tersimpan milik analis sendiri tidak disarankan ke dalam formulir yang seluruh tujuannya adalah membuat catatan <em>orang lain</em>.',
            'groups_heading' => '<strong>Grup</strong>',
            'groups_body' => 'Tab <strong>Grup</strong> di samping <strong>Orang</strong> berisi grup orang bernama &mdash; analis dan pengguna portal layanan mandiri bersama dalam satu grup. Grup dibuat sekali di sini lalu dipakai di seluruh FreeITSM, sehingga Anda dapat memberinya akses ke folder pengetahuan atau menugaskan kursus pelatihan tanpa menyusun daftar yang sama dua kali.',
            'groups_make' => '<strong>Buat satu</strong> dengan <strong>Tambah</strong> di tab Grup: sebuah nama, dan deskripsi yang layak diisi, karena orang berikutnya perlu bisa mengetahui untuk apa grup itu.',
            'groups_add' => '<strong>Tambahkan orang</strong> dengan mencarinya &mdash; pencarian menemukan analis dan pengguna portal sekaligus, sehingga Anda tidak perlu tahu jenis seseorang.',
            'groups_expiry' => '<strong>Beri keanggotaan tanggal berakhir</strong> jika aksesnya bersifat sementara. Tiga teknisi yang bertugas di lokasi selama dua minggu dimasukkan dengan hari terakhir dan keluar dari grup sendiri saat hari itu lewat. Keanggotaan yang kedaluwarsa tetap ada di daftar, ditandai kedaluwarsa, sehingga Anda masih bisa melihat siapa yang punya akses dan sampai kapan.',
            'groups_uses' => '<strong>Kegunaan grup:</strong> memberi akses ke folder pengetahuan, dan menugaskan pelatihan LMS kepada sekelompok orang sekaligus. Perubahan keanggotaan berlaku segera &mdash; tidak ada yang perlu diterapkan ulang sesudahnya.',
            'groups_admin' => '<strong>Siapa pun yang memiliki modul Tiket dapat melihat grup; hanya administrator yang dapat mengubahnya.</strong> Menambahkan seseorang ke grup juga dapat memberi mereka akses ke folder pengetahuan terbatas, jadi ini adalah pemberian akses, bukan sekadar pengarsipan.',
        ],
        'dash' => [
            'heading' => 'Dasbor',
            'intro' => 'Dasbor tiket menyajikan analitik sekilas dengan widget Chart.js yang dapat disesuaikan. Setiap analis memiliki tata letak dasbor sendiri, sehingga Anda dapat berfokus pada metrik yang penting bagi peran Anda &mdash; baik itu beban kerja pribadi, throughput tim, atau kepatuhan SLA.',
            'step1' => '<strong>Buka Pustaka</strong> &mdash; klik Edit Dasbor untuk masuk ke mode edit, lalu jelajahi pustaka widget. Pilih widget bawaan atau buat sendiri dengan memilih jenis grafik dan properti data yang akan diagregasi.',
            'step2' => '<strong>Tambahkan widget</strong> &mdash; klik tombol + pada widget mana pun di pustaka untuk menambahkannya ke dasbor Anda. Widget langsung muncul dan mulai menampilkan data langsung dari database tiket Anda.',
            'step3' => '<strong>Konfigurasikan</strong> &mdash; klik ikon roda gigi pada widget mana pun untuk menyesuaikan judul, jenis grafik (batang, pai, donat, garis, batang bertumpuk, multi-garis), filter rentang tanggal, filter departemen, dan pengelompokan waktu (harian, mingguan, bulanan).',
            'step4' => '<strong>Atur</strong> &mdash; seret dan lepas widget untuk mengubah urutannya. Tata letak Anda disimpan per analis sehingga tetap ada antar sesi.',
            'examples' => 'Contoh widget umum meliputi: <strong>Tiket menurut Status</strong> (grafik donat yang menunjukkan terbuka vs teratasi vs ditutup), <strong>Tiket menurut Prioritas</strong> (grafik batang volume menurut tingkat keparahan), <strong>Volume Mingguan</strong> (grafik garis yang melacak tiket baru dari waktu ke waktu), dan <strong>Beban Kerja Analis</strong> (batang bertumpuk yang menunjukkan tiket aktif setiap analis).',
            'tip' => 'Gunakan filter rentang tanggal pada widget tertentu untuk membandingkan kinerja saat ini dengan periode sebelumnya. Misalnya, tampilan "Bulan Ini vs Bulan Lalu" membantu Anda melihat tren volume tiket lebih awal.',
        ],
        'cal_rota' => [
            'switch_note' => 'Tidak memakai jadwal piket? Nonaktifkan di <strong>Sistem &rarr; Modul &rarr; Ketersediaan &rarr; Fitur tiket</strong> - halaman, pengaturannya, dan <em>siapa yang siaga</em> pada bot War Room hilang, dan tidak ada yang dihapus.',
            'heading' => 'Kalender &amp; jadwal',
            'intro' => 'Dua alat penjadwalan membantu tim Anda tetap teratur: kalender tiket yang memvisualisasikan beban kerja dari waktu ke waktu, dan jadwal staf untuk mengelola shift dan ketersediaan siaga.',
            'cal_heading' => '<strong>Tampilan kalender</strong>',
            'cal_body' => 'Kalender menampilkan setiap tiket yang telah Anda jadwalkan &mdash; lewat <strong>Jadwalkan pekerjaan</strong>, yang ada di tiket itu sendiri dan di menu klik kanan kotak masuk &mdash; sebagai blok berwarna pada waktu terjadwalnya, digambar sesuai <strong>panjang sebenarnya</strong> dan bukan satu jam tetap. Blok merah berprioritas <em>Tinggi</em>, hijau <em>Rendah</em>, biru untuk yang lain. Gunakan <em>Hari ini</em>, tanda panah <em>&lt;</em> / <em>&gt;</em>, dan tombol <strong>Bulan / Minggu / Hari</strong> untuk bernavigasi.',
            'cal_scope' => '<strong>Milik saya atau Semua orang.</strong> Kalender terbuka pada pekerjaan terjadwal Anda sendiri, dengan sakelar <strong>Semua orang</strong> di samping tombol tampilan; pilihan Anda diingat. Pada Semua orang, setiap tiket membawa <strong>warna untuk pemiliknya</strong>, dengan legenda yang menyebut orang yang benar-benar tampil di layar, dan mengarahkan kursor ke tiket memberi tahu milik siapa tanpa perlu berpaling. Tidak ada yang disembunyikan dari siapa pun &mdash; ini adalah tiket yang sama yang sudah tercantum di kotak masuk.',
            'cal_edit' => '<strong>Menata ulang pekerjaan.</strong> <strong>Seret tiket</strong> ke hari atau waktu yang berbeda: pada tampilan Bulan waktunya tetap, dan pada tampilan Minggu dan Hari tiket mengambil waktu tempat Anda melepasnya, dibulatkan ke seperempat jam terdekat. Panjangnya tidak pernah berubah &mdash; menyeret berarti <em>mulai saat itu</em>, bukan <em>buat lebih lama</em>. Atau <strong>klik tiket</strong> untuk membukanya, tempat Anda dapat mengubah tanggal, waktu, durasi, dan pengaturan sepanjang hari, atau menghapus jadwalnya sama sekali. Kalender juga <strong>menyegarkan diri setiap beberapa detik</strong>, sehingga rekan yang menjadwalkan sesuatu muncul tanpa Anda memuat ulang &mdash; dan penyegaran ditunda saat Anda membuka tiket atau sedang menyeret.',
            'cal_month' => '<strong>Tampilan bulan</strong> &mdash; kisi 6 baris klasik dengan strip header hari; setiap sel hari menampilkan hingga tiga pil tiket beserta waktu mulainya, ditambah tautan <em>+N lagi</em> yang membawa Anda ke tampilan Hari untuk tanggal itu. Hari ini disorot.',
            'cal_week' => '<strong>Tampilan minggu</strong> &mdash; Sen&ndash;Min di bagian atas di atas garis waktu vertikal 24 jam. Tiket ditampilkan sesuai panjang terjadwalnya, jadi pekerjaan 15 menit dan pembangunan ulang seharian terlihat berbeda. Tiket sepanjang hari berada sebagai bilah tipis di bagian atas harinya dan tidak memenuhi seluruh kolom. Kolom hari ini disorot; header hari tetap di tempat sementara kisi jam bergulir.',
            'cal_day' => '<strong>Tampilan hari</strong> &mdash; satu kolom tinggi untuk hari yang dipilih dengan garis waktu 24 jam yang sama. Tiket ditampilkan sebagai blok lebih besar yang menunjukkan <code>ticket_number &mdash; subject</code> dan waktu mulai; klik salah satunya untuk membuka detailnya atau mengubah kapan pekerjaan itu terjadi.',
            'rota_heading' => '<strong>Jadwal staf</strong>',
            'rota_body' => 'Halaman jadwal memungkinkan ketua tim dan manajer menjadwalkan shift analis sepanjang minggu. Tentukan jam kerja standar, tetapkan periode siaga, dan tandai hari libur atau ketidakhadiran agar tim selalu tahu siapa yang tersedia.',
            'rota_step1' => '<strong>Lihat kisi jadwal</strong> &mdash; jadwal menampilkan analis di satu sumbu dan hari di sumbu lainnya, dengan blok shift yang menunjukkan cakupan sekilas.',
            'rota_step2' => '<strong>Tambah atau edit shift</strong> &mdash; klik sebuah sel untuk menetapkan tipe shift (mis. Pagi, Sore, Malam, Siaga). Perubahan langsung tersimpan.',
            'rota_step3' => '<strong>Rencanakan ke depan</strong> &mdash; maju per minggu untuk menyusun jadwal lebih awal. Ini memastikan cakupan yang memadai pada periode sibuk, hari libur, atau hari pelatihan yang sudah diketahui.',
            'rota_step4' => '<strong>Isi beberapa sel sekaligus</strong> &mdash; <strong>klik kanan</strong> sebuah sel dan pilih <em>Salin</em> untuk mengambil shift di dalamnya, lalu klik kanan sel lain dan <em>Tempel</em>. Untuk lebih dari satu sel, <strong>seret melintasi blok</strong> sel (atau ctrl-klik sel satu per satu) dan tempel ke semuanya. Mengarahkan kursor ke <strong>judul hari</strong> menyorot seluruh hari itu, dan mengarahkan ke <strong>nama analis</strong> menyorot seluruh minggunya &mdash; klik kanan salah satunya dan tempel ke semuanya. Jika sebagian sel sudah memiliki shift, menu menawarkan kedua cara dengan kata-kata jelas &mdash; <em>Tempel ke semua 7</em> dan <em>Tempel ke 6 sel kosong</em> &mdash; sehingga Anda memilih sebelum melakukannya, bukan sesudahnya. Menimpa meminta Anda mengonfirmasi dan menyebut berapa shift yang diganti; mengisi celah langsung terjadi, karena tidak ada yang hilang. Menu yang sama juga akan <strong>mengosongkan</strong> satu hari, satu minggu, atau pilihan, lagi-lagi setelah memberi tahu berapa shift yang akan dihapus.',
            'rota_step5' => '<strong>Salin satu hari atau satu minggu penuh untuk satu orang</strong> &mdash; klik kanan <strong>judul hari</strong> dan pilih <em>Salin</em> untuk mengambil setiap shift pada hari itu, atau <strong>nama analis</strong> untuk mengambil seluruh minggunya. Menempel ke hari lain, atau analis lain, membuatnya sama: shift yang tidak ada pada salinan dikosongkan, sehingga Anda mendapat hari yang Anda salin, bukan campuran keduanya. Hari hanya dapat ditempel ke hari lain dan analis hanya ke analis lain &mdash; satu hari adalah satu shift <em>per orang</em> dan satu minggu adalah satu shift <em>per hari</em>, jadi tidak ada cara yang masuk akal untuk menumpangkan yang satu pada yang lain. Jika dicoba, menu menyatakannya, dan menyebut ke mana bisa ditempel.',
            'rota_step6' => '<strong>Salin satu minggu penuh</strong> &mdash; <strong>Salin minggu</strong> dan <strong>Tempel minggu</strong> di kanan atas mengambil setiap shift pada minggu yang Anda lihat dan menaruhnya ke minggu lain, cara tercepat untuk membangun jadwal berulang. Menempel <em>mengganti</em> minggu tujuan, jadi konfirmasi memberi tahu berapa entri yang akan dihapus. Ini hanya menyentuh hari dan orang yang benar-benar ditampilkan kisi kepada Anda.',
            'tip' => 'Gabungkan kalender dan jadwal untuk perencanaan kapasitas yang efektif. Jika kalender menunjukkan lonjakan tiket setiap Senin pagi, pastikan jadwal memiliki cakupan tambahan pada slot itu.',
        ],
        'settings' => [
            'heading' => 'Pengaturan',
            'intro' => 'Halaman Pengaturan adalah tempat Anda mengonfigurasi elemen dasar sistem tiket Anda. Semua nilai pencarian, target SLA, integrasi email, dan bidang kustom dikelola di sini.',
            'sla_callout_title' => 'Manajemen SLA &mdash; panduan lengkap',
            'sla_callout_body' => 'Opsi yang dapat dikonfigurasi, kalender bisnis, status jeda, notifikasi pelanggaran, penyiapan cron job, beserta contoh kasus untuk tim satu zona waktu dan lintas zona waktu. Cukup panjang untuk punya halaman sendiri.',
            'card_dept_title' => 'Departemen',
            'card_dept_body' => 'Buat departemen seperti IT, HR, dan Keuangan. Setiap departemen menjadi folder di kotak masuk dan filter di dasbor',
            'card_types_title' => 'Tipe tiket',
            'card_types_body' => 'Tentukan jenis permintaan yang ditangani meja layanan Anda: Insiden, Permintaan Layanan, Masalah, Perubahan. Tipe membantu analis mengklasifikasikan pekerjaan',
            'card_type_rules_title' => 'Tipe untuk tiket baru',
            'card_type_rules_body' => 'Di bawah Tipe tiket, beri setiap tiket baru sebuah tipe ketika tidak ada yang memilihnya: sebuah default, dan aturan sebelumnya - berdasarkan cara tiket masuk (email, portal, web chat, telepon, pemantauan...), kotak surat, asal, departemen, kata dalam subjek, atau domain peminta. Aturan pertama yang cocok menang; Coba menunjukkan tipe mana yang akan didapat tiket',
            'card_priorities_title' => 'Prioritas',
            'card_priorities_body' => 'Atur tingkat prioritas dengan nama, warna, dan urutan. Setiap prioritas terhubung ke target SLA untuk respons dan resolusi',
            'card_statuses_title' => 'Status',
            'card_statuses_body' => 'Sesuaikan tahapan siklus hidup tiket. Status default meliputi Baru, Terbuka, Sedang Dikerjakan, Tertunda, Teratasi, dan Ditutup',
            'card_categories_title' => 'Kategori',
            'card_categories_body' => 'Kelompokkan tiket menurut area teknis: Perangkat Keras, Perangkat Lunak, Jaringan, Akses. Kategori menjadi dasar rincian pelaporan',
            'card_sla_title' => 'Target SLA',
            'card_sla_body' => 'Tentukan target waktu respons dan resolusi per prioritas. Pengatur waktu SLA muncul pada tiket dan memicu peringatan pelanggaran',
            'card_email_title' => 'Impor email',
            'card_email_body' => 'Hubungkan kotak surat (Exchange, Microsoft 365) untuk mengimpor email secara otomatis sebagai tiket baru. Balasan tersambung kembali ke tiket yang ada',
            'card_custom_title' => 'Bidang kustom',
            'card_custom_body' => 'Tambahkan bidang Anda sendiri pada tiket untuk data yang perlu dicatat organisasi Anda yang tidak tercakup oleh kumpulan bidang default',
            'card_templates_title' => 'Template email',
            'card_templates_body' => 'Konfigurasikan template notifikasi yang dikirim ke pengguna akhir saat tiket dibuat, diperbarui, teratasi, atau untuk survei CSAT. Sematkan kode gabungan seperti [requester_name] dan [csat_link]',
            'card_checklists_title' => 'Daftar periksa',
            'card_checklists_body' => 'Tentukan apa yang terjadi saat seseorang menutup tiket yang masih memiliki langkah daftar periksa wajib yang belum selesai: <strong>peringatkan</strong> dan catat catatan internal yang menyebut langkah-langkahnya serta siapa yang menutup, atau <strong>blokir</strong> penutupan sampai selesai. Diberlakukan di mana pun tiket dapat ditutup - termasuk tindakan massal, REST API, dan otomatisasi alur kerja',
            'card_custom_fields_title' => 'Bidang kustom',
            'card_custom_fields_body' => 'Susun detail tambahan yang dibutuhkan suatu jenis tiket - teks, angka, tanggal, ya / tidak, dropdown berisi opsi Anda sendiri, alamat web atau email - dan tautkan masing-masing ke beberapa tipe tiket atau ke semuanya. Setiap bidang memilih apakah harus diisi <strong>saat tiket dicatat</strong> (formulir Tiket baru, REST API, dan, jika diminta, portal), <strong>sebelum ditutup</strong> (mengikuti aturan Bidang wajib), atau keduanya, dan apakah <strong>peminta ditanyai</strong> di portal - tempat pemilih tipe tiket muncul begitu tipe itu mengubah apa yang ditanyakan. Jawaban tampil di panel properti tiket dan riwayatnya. Mengubah tipe tiket menyembunyikan jawaban yang tidak dimiliki tipe barunya, dan tidak pernah menghapusnya',
            'card_mandatory_title' => 'Bidang wajib',
            'card_mandatory_body' => 'Centang bidang yang harus diisi sebelum tiket dapat ditutup - kategori, kode resolusi, pemilik, dan sebagainya. Lalu pilih apa yang terjadi saat seseorang menutup tiket dengan bidang kosong: <strong>peringatkan</strong>, <strong>peringatkan dan kirim email</strong> kepada seseorang seperti manajer layanan, atau <strong>tolak</strong> penutupan. Sakelar terpisah mencatatnya pada tiket sebagai catatan internal. Bidang yang dinonaktifkan untuk suatu perusahaan tidak pernah wajib, dan penggabungan tiket tidak pernah memicunya. Diberlakukan di mana pun tiket dapat ditutup - termasuk tindakan massal, REST API, dan otomatisasi alur kerja',
            'card_cleanup_title' => 'AI Perapian Balasan',
            'card_cleanup_body' => 'Kunci Anthropic + model + nada untuk tombol ✨ Cleanup pada editor balasan. Kunci terpisah dari fitur AI lainnya untuk penagihan yang terperinci',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'Mode pengiriman (mati / otomatis / manual), jeda, pengaman satu per tiket, skala (bintang atau emoji). Lihat bagian 6 untuk alur lengkapnya',
            'email_heading' => '<strong>Impor email secara rinci</strong>',
            'email_body' => 'Fitur impor email terhubung ke kotak surat bersama Anda dan menarik pesan baru sebagai tiket. Saat pengguna akhir mengirim email ke alamat dukungan Anda (mis. support@yourcompany.com), FreeITSM membuat tiket dengan subjek email sebagai judul dan isi email sebagai deskripsi. Jika pengirim membalas email notifikasi, balasan itu disambungkan ke tiket yang ada dan tidak membuat duplikat.',
            'email_step1' => '<strong>Konfigurasikan kotak surat</strong> &mdash; buka Pengaturan dan masukkan kredensial Exchange atau Microsoft 365 Anda. Autentikasi OAuth didukung untuk koneksi aman tanpa kata sandi.',
            'email_step2' => '<strong>Atur interval pemeriksaan</strong> &mdash; pilih seberapa sering FreeITSM memeriksa kotak surat untuk pesan baru. Interval lebih pendek berarti tiket dibuat lebih cepat.',
            'email_step3' => '<strong>Petakan default</strong> &mdash; atur departemen, tipe, dan prioritas default untuk tiket yang dibuat dari email. Analis dapat menyesuaikannya setelah impor.',
            'email_thread_note' => '<strong>Balasan tanpa nomor tiket</strong> &mdash; setiap email yang dikirim FreeITSM membawa nomor tiket, sehingga balasannya selalu menemukan tiketnya. Ketika seseorang membalas email pertamanya <em>sendiri</em> (misalnya untuk menambahkan lampiran yang terlupa), tidak ada nomor untuk ditemukan, dan secara default balasan itu memulai tiket baru. Atur Tiket &rarr; Pengaturan &rarr; Umum &rarr; <strong>Balasan tanpa nomor tiket</strong> ke <strong>Bergabung dengan tiket tempat percakapannya berada</strong> dan balasan masuk ke tiket yang dibuka email pertama itu, membukanya kembali jika sudah ditutup (bila pembukaan kembali diaktifkan). Hanya email di kotak surat yang sama yang dicocokkan.',
            'email_reply_to_note' => '<strong>Siapa yang dijawab Balas</strong> &mdash; secara default kotak Balas ditujukan kepada orang pada pesan yang sedang Anda baca. Jika rekan peminta bergabung di utas dan Anda lebih suka selalu menjawab peminta, atur Tiket &rarr; Pengaturan &rarr; Umum &rarr; <strong>Balasan ditujukan ke</strong> ke <strong>Peminta tiket</strong>. Anda selalu dapat mengubah alamat sebelum mengirim.',
            'tip' => 'Gunakan template email untuk menjaga nada yang profesional dan konsisten dalam semua komunikasi dengan pengguna akhir. Template mendukung placeholder dinamis untuk referensi tiket, nama peminta, nama analis, dan status.',
            'closemsg_heading' => '<strong>Pesan sekali pakai saat Anda menutup tiket</strong>',
            'closemsg_body' => 'Taruh <code>[ticket_closed_message]</code> di mana saja dalam template <strong>Tiket ditutup</strong> yang aktif, dan sejak itu, mengubah tiket ke status tertutup meminta analis menulis satu kalimat - <em>&ldquo;charger cadangan ada di meja Anda&rdquo;</em>, <em>&ldquo;ditutup sesuai kesepakatan lewat telepon&rdquo;</em>. Apa pun yang mereka ketik muncul persis di tempat Anda menaruh placeholder, sehingga Anda tetap mengendalikan kata-kata di sekitarnya. Ini bukan pengaturan dan tidak ada yang menyimpannya: satu catatan, satu tiket, satu email. Jika tidak mengetik apa pun, barisnya sederhana tidak ada - tanpa celah, tanpa tanda baca nyasar.',
            'closemsg_note' => '<strong>Prompt hanya muncul jika placeholder benar-benar ada di template.</strong> Tanpa itu, apa pun yang diketik analis akan dibuang diam-diam, dan setiap meja layanan yang tidak menginginkan ini akan mendapat satu klik tambahan pada setiap penutupan. Jadi fitur ini aktif sendiri saat Anda mengonfigurasinya dan tidak mengganggu jika tidak.',
            'cat_heading' => '<strong>Kategori, dan dua bidang di sampingnya</strong>',
            'cat_body' => '<em>Tipe</em> tiket menyatakan jenis hal ini; <em>kategori</em> menyatakan tentang apa. Susun daftarnya di <strong>Pengaturan &rarr; Kategori</strong>, bersama sakelar yang menentukan apakah semua ini muncul pada tiket sama sekali.',
            'cat_card_one_title' => 'Kategori',
            'cat_card_one_body' => 'Apa yang dilaporkan pada tiket, dipilih saat tiket diajukan. Tiket hanya memiliki satu, sehingga laporan kategori Anda selalu berjumlah sama dengan tiket yang benar-benar Anda terima.',
            'cat_card_close_title' => 'Kategori saat ditutup',
            'cat_card_close_body' => 'Daftar yang sama ditanyakan lagi saat tiket selesai. Biasanya analis hanya mengonfirmasinya &mdash; fitur ini terbukti berguna pada tiket yang tebakan pertamanya keliru, dan dari situlah Anda tahu bahwa dua belas dari tiga puluh tujuh "masalah printer" Anda ternyata jaringan.',
            'cat_card_res_title' => 'Kode resolusi',
            'cat_card_res_body' => 'Bagaimana tiket berakhir, bukan tentang apa tiket itu &mdash; "Diperbaiki dari jarak jauh", "Pelatihan diberikan", "Tidak ditemukan gangguan". Sepuluh kode yang masuk akal sudah tersedia sejak awal dan semuanya dapat Anda ubah.',
            'cat_rule_off' => '<strong>Ketiganya mulai dalam keadaan nonaktif.</strong> Susun daftar Anda dulu, lalu aktifkan yang Anda inginkan. Masing-masing dapat diatur berbeda untuk setiap perusahaan.',
            'cat_rule_levels' => 'Kategori dapat memiliki subkategori hingga tiga tingkat, dan tidak ada tingkat yang wajib.',
            'cat_rule_type' => 'Kategori dapat dikaitkan dengan satu tipe tiket, sehingga "Onboarding pengguna" hanya ditawarkan pada permintaan layanan. Kaitan itu milik kategori tingkat atas dan subkategorinya mengikuti.',
            'cat_rule_typechange' => '<strong>Mengubah tipe tiket menghapus kategori yang milik tipe lama</strong>, dan menyatakannya di layar. Kategori yang tidak terkait tipe mana pun tetap ada setelah perubahan.',
            'cat_rule_portal' => 'Centang <em>Pelanggan dapat memilih ini</em> untuk menawarkan kategori di portal layanan mandiri. Peminta melihat daftar singkat dalam bahasa sehari-hari sementara analis melihat seluruh pohon.',
            'cat_rule_retire' => 'Nonaktifkan kategori untuk mempensiunkannya &mdash; kategori tetap pada tiket yang sudah memilikinya dan tidak lagi ditawarkan pada tiket baru. Itu hampir selalu lebih baik daripada menghapus, yang ditolak selama masih ada yang menggunakannya.',
            'cat_rule_report' => 'Ketiganya dapat ditampilkan dalam grafik di dasbor tiket. Dua grafik kategori digulung ke tingkat atas, dan tiket tanpa isian dihitung sebagai <em>Belum dikategorikan</em> dan tidak disembunyikan.',
            'cat_tip' => 'Jika Anda tidak yakin harus mulai dari mana, biarkan kategori kosong dan aktifkan <strong>Kode resolusi</strong> saja. Bidang inilah yang paling cepat mengubah apa yang Anda lakukan &mdash; seperlima tiket Anda kembali sebagai "Pelatihan diberikan" adalah masalah dokumentasi, bukan masalah IT.',
        ],
        'tips' => [
            'heading' => 'Tips singkat',
            'search_title' => 'Cari apa saja',
            'search_body' => 'Modal pencarian memeriksa referensi tiket, subjek, nama peminta, dan alamat email. Gunakan untuk menemukan tiket terkait dengan cepat saat pengguna menelepon tentang masalah yang sudah ada.',
            'sla_title' => 'Pantau SLA Anda',
            'sla_body' => 'Pengatur waktu SLA terlihat pada setiap tiket di panel baca. Indikator berkode warna berubah kuning saat pelanggaran mendekat dan merah saat target terlewati, sehingga Anda dapat memprioritaskan sesuai kebutuhan.',
            'reply_title' => 'Balas dari kotak masuk',
            'reply_body' => 'Anda tidak perlu membuka klien email untuk menanggapi pengguna akhir. Gunakan tombol Balas di panel baca untuk mengirim pesan langsung. Pesan otomatis tersambung ke tiket.',
            'reply_to_title' => 'Kepada siapa Balas ditujukan',
            'reply_to_body' => 'Balas ditujukan kepada orang pada pesan yang sedang Anda baca. Jika Anda lebih suka selalu ke peminta tiket, ubah <strong>Balasan ditujukan ke</strong> di Tiket &rarr; Pengaturan &rarr; Umum. Bagaimanapun, Anda dapat mengubah alamat, atau menambahkan orang di Cc, sebelum mengirim.',
            'trail_title' => 'Gunakan jejak aktivitas',
            'trail_body' => 'Sebelum mengerjakan tiket, gulir jejak aktivitasnya. Catatan analis sebelumnya, email, dan perubahan bidang memberi Anda konteks lengkap sehingga Anda tidak meminta pengguna mengulang informasi.',
            'dash_title' => 'Dasbor untuk manajer',
            'dash_body' => 'Susun dasbor dengan widget untuk tingkat kepatuhan SLA, waktu resolusi rata-rata, dan tiket menurut departemen. Bagikan dalam rapat tim untuk mendorong perbaikan berkelanjutan.',
            'rota_title' => 'Rencanakan dengan jadwal',
            'rota_body' => 'Isi jadwal setidaknya dua minggu sebelumnya. Dikombinasikan dengan tampilan kalender, ini membantu Anda mengenali celah cakupan sebelum menjadi masalah bagi waktu respons.',
            'drag_title' => 'Seret untuk triase',
            'drag_body' => 'Seret tiket dari daftar ke folder untuk memperbaruinya tanpa membukanya. Subfolder Departemen + status memperbarui keduanya sekaligus. Perluasan otomatis membuat status bersarang dapat dijangkau saat menyeret.',
            'dbl_title' => 'Klik dua kali untuk layar penuh',
            'dbl_body' => 'Satu klik menampilkan pratinjau tiket di panel baca; klik dua kali membukanya dalam mode layar penuh untuk pekerjaan yang butuh fokus. Klik ikon maksimalkan di samping subjek untuk kembali.',
            'rightclick_title' => 'Klik kanan untuk tindakan cepat',
            'rightclick_body' => 'Klik kanan tiket mana pun untuk mengubah status, prioritas, atau penerima tugas dengan satu klik, plus tautkan-CMDB dan catat-waktu, semuanya tanpa berpindah dari tiket yang sedang Anda baca.',
            'ai_title' => 'Biarkan AI merapikan balasan Anda',
            'ai_body' => 'Ketik draf kasar (atau sekadar poin-poin) lalu klik <strong>✨ Cleanup</strong> &mdash; Claude menulis ulang menjadi email yang layak dengan salam, perbaikan tata bahasa, dan penutup. Tautan Urungkan muncul selama 30 detik.',
            'feedback_title' => 'Minta umpan balik',
            'feedback_body' => 'Aktifkan CSAT di <strong>Pengaturan &rarr; CSAT</strong> untuk mensurvei peminta secara otomatis saat tiket mereka ditutup. Tren per analis ada di <code>tickets/csat/</code> &mdash; berharga untuk percakapan pengembangan.',
            'precreate_title' => 'Buat pengguna akhir lebih dulu',
            'precreate_body' => 'Tombol navigasi <strong>Pengguna</strong> memungkinkan Anda menambahkan pengguna sebelum mereka perlu mencatat tiket &mdash; kosongkan kata sandi dan mereka dapat mengklaim akunnya sendiri lewat portal layanan mandiri.',
        ],
        'companies' => [
            'heading' => 'Perusahaan &amp; perutean email',
            'intro' => 'Jika instalasi Anda melayani lebih dari satu perusahaan (misalnya penyedia IT yang mendukung beberapa klien), tiket setiap perusahaan dipisahkan. Bagian ini menjelaskan bagaimana email masuk menemukan perusahaan yang tepat.',
            'switcher_body' => '<strong>Pengalih perusahaan</strong> muncul di header. Pengalih ini menentukan perusahaan tempat Anda bekerja &mdash; daftar tiket, folder, dan jumlahnya hanya menampilkan perusahaan tersebut, dan setiap tiket yang Anda buat dicatat ke perusahaan itu. Staf yang memiliki akses ke beberapa perusahaan dapat berpindah di antaranya; perusahaan saat ini selalu ditampilkan agar Anda tidak membalas dalam konteks yang salah. Kelola perusahaan itu sendiri di <strong>Sistem &rarr; Perusahaan</strong>.',
            'mailboxes_heading' => 'Setiap kotak surat termasuk salah satu dari dua jenis &mdash; inilah yang menentukan perutean:',
            'card_pinned_title' => 'Kotak surat tersemat',
            'card_pinned_body' => 'Khusus untuk satu perusahaan (misalnya <code>itsupport@</code> milik klien sendiri). <strong>Semua</strong> suratnya dicatat ke perusahaan itu &mdash; pengirim diabaikan &mdash; dan balasan keluar dari kotak surat ini, sehingga klien melihat help desk mereka sendiri dari awal sampai akhir.',
            'card_shared_title' => 'Kotak surat penerimaan bersama',
            'card_shared_body' => 'Satu alamat yang melayani banyak perusahaan (misalnya <code>support@theprovider.com</code> milik penyedia). Alamat ini tidak bisa mengetahui perusahaan hanya dari alamatnya, jadi perusahaan ditentukan dari <strong>siapa yang mengirim email</strong>. Ini pengaturan yang direkomendasikan untuk penyedia dengan banyak klien.',
            'routing_heading' => 'Cara kotak surat penerimaan bersama memilih perusahaan',
            'routing_body' => 'Untuk setiap email masuk, sistem mencoba hal-hal berikut secara berurutan, dan kecocokan pertama yang dipakai:',
            'flow_reply' => 'Balasan tiket',
            'flow_sender' => 'Pengirim dikenal',
            'flow_domain' => 'Domain dikenal',
            'flow_triage' => 'Triase',
            'rule_reply' => '<strong>1. Balasan untuk tiket yang sudah ada</strong> &mdash; dikenali dari referensinya, email bergabung ke tiket itu dan tetap memakai perusahaannya.',
            'rule_sender' => '<strong>2. Alamat pengirim tertentu</strong> yang dipetakan ke perusahaan (mis. <code>jane@gmail.com</code> &rarr; Acme) &mdash; perusahaan itu. Diperiksa sebelum domain, sehingga berfungsi bahkan untuk alamat pribadi/webmail.',
            'rule_domain' => '<strong>3. Domain pengirim</strong> yang dipetakan ke perusahaan (mis. siapa pun di <code>@acme.com</code> &rarr; Acme) &mdash; perusahaan itu.',
            'rule_triage' => '<strong>4. Tidak ada kecocokan</strong> &mdash; email masuk ke antrean <strong>triase</strong> alih-alih hilang (lihat di bawah).',
            'keys_heading' => 'Domain &amp; pengirim tertentu (diatur per perusahaan di Sistem &rarr; Perusahaan)',
            'keys_body' => 'Inilah kunci yang dicocokkan oleh kotak surat penerimaan bersama. Setiap perusahaan mencantumkan domain email yang dimilikinya dan, secara opsional, alamat pengirim individual.',
            'card_domains_title' => 'Domain email',
            'card_domains_body' => 'Domain yang dimiliki perusahaan (acme.com, acme.co.uk). Setiap pengirim dari domain terdaftar diarahkan ke perusahaan itu. Satu domain hanya dapat dimiliki satu perusahaan.',
            'card_senders_title' => 'Pengirim tertentu',
            'card_senders_body' => 'Alamat individual yang dipetakan ke perusahaan, diperiksa sebelum domain. Gunakan untuk pekerja lepas atau klien kecil yang mengirim email dari alamat pribadi.',
            'card_public_title' => 'Penyedia publik',
            'card_public_body' => 'Gmail, Outlook, Yahoo, dan sejenisnya tidak dapat dipetakan sebagai domain (banyak orang yang tidak berhubungan memakainya bersama) &mdash; petakan alamat persisnya sebagai pengirim tertentu.',
            'triage_heading' => 'Antrean triase &mdash; jaring pengaman',
            'triage_body' => 'Jika email penerimaan bersama tidak cocok dengan perusahaan mana pun, email itu masuk ke <strong>Triase</strong> (dibuka dari pengalih perusahaan, dengan jumlah langsung) alih-alih hilang. Setiap item menampilkan pengirim, domain, subjek, dan kotak surat tempat email tiba. Catat ke sebuah perusahaan dalam satu langkah:',
            'triage_create' => 'Pilih perusahaan yang sudah ada, atau buat yang baru saat itu juga.',
            'triage_assign' => 'Untuk domain biasa, Anda dapat memilih untuk <strong>mengarahkan domain itu</strong> ke perusahaan; untuk alamat publik/webmail, Anda dapat memilih untuk <strong>selalu mencatat pengirim itu</strong> di sana.',
            'triage_sweep' => 'Kedua pilihan ini <em>menyapu</em>: semua email antrean lain dari domain atau alamat itu ikut dipindahkan, dan surat berikutnya diarahkan otomatis &mdash; jadi Anda hanya perlu memilah pengirim tertentu satu kali.',
            'triage_tip' => 'Tidak ada yang pernah hilang. Surat yang tidak cocok menunggu di triase sampai seseorang mencatatnya; tiket yang belum dicatat tetap tampil di perusahaan default untuk sementara.',
            'test_heading' => 'Uji perutean Anda sebelum digunakan',
            'test_body' => 'Di <strong>Sistem &rarr; Uji perutean email</strong> Anda dapat berpura-pura sebuah email tiba &mdash; pilih kotak surat, ketik alamat pengirim &mdash; dan lihat persis perusahaan mana yang akan menerima tiket baru (atau bahwa email akan masuk ke triase) dan aturan mana yang memutuskannya. Pengujian ini tidak membuat apa pun; hanya membaca pengaturan Anda.',
            'settings_heading' => 'Pengaturan: dibagi secara default, disesuaikan jika perlu',
            'settings_body' => 'Beberapa Pengaturan ini dapat <strong>disesuaikan per perusahaan</strong>; yang lain sengaja tetap dibagi. Jika sebuah pengaturan berupa daftar opsi sederhana &mdash; seperti <strong>tipe tiket</strong> dan <strong>asal</strong> &mdash; beralihlah ke konteks perusahaan dan Anda akan melihat default bersama (masing-masing dengan ikon mata untuk menyembunyikan yang tidak dipakai) ditambah opsi yang ditambahkan khusus untuk perusahaan itu. Anda tidak dapat menyembunyikan atau menghapus opsi selama tiket terbuka masih memakainya, dan default bersama itu sendiri diubah dari perusahaan MSP / default.',
            'settings_custom_title' => 'Disesuaikan per perusahaan',
            'settings_custom_body' => 'Tipe tiket &amp; asal (sekarang), serta kategori, SLA &amp; jam kerja (segera hadir) &mdash; hal-hal yang memang berbeda dari satu klien ke klien lain.',
            'settings_global_title' => 'Dibagi di setiap perusahaan',
            'settings_global_body' => 'Status dan prioritas tetap sama di mana-mana, sehingga pelaporan lintas perusahaan dan SLA tetap konsisten; begitu pula tim, jadwal, dan kotak surat Anda &mdash; operasi Anda sendiri, bukan milik klien.',
            'allview_heading' => '<strong>Satu papan untuk semua perusahaan</strong>',
            'allview_body' => 'Pengalih perusahaan di header memiliki opsi <strong>Semua perusahaan</strong>. Setiap tiket yang boleh Anda lihat muncul dalam satu daftar, dengan setiap baris menampilkan perusahaan pemiliknya &mdash; berguna jika Anda mendukung beberapa entitas dan menginginkan satu tampilan untuk hari itu tanpa kehilangan jejak milik siapa yang mana.',
            'allview_card_scope_title' => 'Tidak memberi akses baru',
            'allview_card_scope_body' => '"Semua" berarti setiap perusahaan yang sebelumnya sudah bisa Anda jangkau satu per satu. Analis yang mendukung dua dari tiga entitas Anda melihat tepat dua itu, dan analis dengan satu perusahaan melihat tampilan perusahaan itu saja.',
            'allview_card_props_title' => 'Setiap entitas tetap terpisah',
            'allview_card_props_body' => 'Saat Anda membuka tiket, tipe, asal, kategori, dan daftar resolusinya adalah milik perusahaan <em>itu</em> &mdash; sehingga kategori yang dimiliki satu entitas tetapi tidak oleh yang lain tidak pernah bisa diterapkan pada tiket yang salah.',
            'allview_card_new_title' => 'Tiket baru menanyakan perusahaan',
            'allview_card_new_body' => 'Tidak ada satu perusahaan aktif yang bisa diasumsikan, dan pilihan itu menentukan nomor tiket, kotak surat asal balasan, dan SLA yang berlaku. Daftar tipe terisi setelah Anda memilih.',
            'allview_rule_chip' => 'Tiket yang masuk lewat email atau portal tetapi belum diarahkan ditandai <strong>Belum diarahkan</strong> alih-alih ditampilkan di Default, sehingga menonjol untuk triase.',
            'allview_rule_reply' => 'Balasan tetap keluar dari kotak surat tempat tiket tiba &mdash; itu mengikuti tiket, bukan tampilan, sehingga papan gabungan tidak bisa mengirim dari alamat yang salah.',
            'allview_rule_knowledge' => '<strong>Tanya AI</strong> mencari di setiap perusahaan yang dapat Anda lihat selama tampilan gabungan aktif, bukan hanya satu. Artikel yang dibagikan ke semua perusahaan tetap disertakan dalam kedua kasus.',
            'allview_rule_trash' => '<strong>Mengosongkan tempat sampah tidak pernah mencakup banyak perusahaan.</strong> Tindakan ini selalu berlaku untuk satu perusahaan yang terakhir Anda pilih, karena "hapus semuanya di tempat sampah" di beberapa entitas sekaligus bukan yang dimaksud siapa pun.',
            'allview_rule_other' => 'Hanya daftar tiket yang meluas. Aset, perubahan, tugas, dan CMDB tetap menampilkan satu perusahaan pada satu waktu &mdash; beralihlah ke perusahaan itu untuk bekerja di dalamnya.',
            'privacy_heading' => 'Tiket setiap perusahaan tetap privat',
            'privacy_body' => 'Saat Anda bekerja dalam konteks sebuah perusahaan, Anda hanya melihat tiket perusahaan <strong>itu</strong> &mdash; di daftar, di pencarian, di dasbor, dan di setiap tiket yang Anda buka (termasuk email, lampiran, catatan, dan riwayatnya). Anggota staf hanya dapat menjangkau tiket jika diberi akses ke perusahaannya (Anda memilih perusahaan setiap analis di Sistem &rarr; Analis, atau memberi akses ke seluruh tim di Sistem &rarr; Tim), sehingga tidak mungkin tersasar ke data klien lain. Pemisahan ini diterapkan di mana-mana di balik layar, bukan sekadar disembunyikan dari tampilan. Pada instalasi satu perusahaan, ini otomatis dan tidak terlihat &mdash; hanya ada satu perusahaan, jadi semuanya otomatis miliknya.',
            'tip' => 'Pada instalasi satu perusahaan, tidak ada satu pun dari ini yang muncul &mdash; hanya ada satu perusahaan, setiap tiket miliknya, dan tidak ada pengalih atau triase. Fitur-fitur ini baru aktif setelah perusahaan kedua ada.',
