    'help_sla' => [
        'page_title' => 'Manajemen SLA',
        'back_link' => '&larr; Kembali ke panduan Tiket',
        'sidebar_title' => 'Panduan SLA',
        'hero_title' => 'Manajemen SLA',
        'hero_sub' => 'Target respons dan resolusi yang memperhitungkan jam kerja, dengan notifikasi pelanggaran per departemen',
        'nav' => [
            'overview' => 'Ikhtisar',
            'building_blocks' => 'Elemen dasar',
            'behaviour_settings' => 'Pengaturan perilaku',
            'breach_notifications' => 'Notifikasi pelanggaran',
            'cron_setup' => 'Penyiapan cron job',
            'worked_examples' => 'Contoh kasus',
            'troubleshooting' => 'Pemecahan masalah',
        ],
        'overview' => [
            'heading' => 'Ikhtisar',
            'sub' => 'Apa itu SLA, mengapa penting, dan bagaimana mesin SLA FreeITSM bekerja secara garis besar.',
            'p1' => 'Service Level Agreement (SLA) adalah janji tentang seberapa cepat tim Anda merespons dan menyelesaikan sebuah tiket. FreeITSM melacak dua jam per tiket: <strong>respons</strong> (waktu dari pembuatan tiket hingga tindakan analis pertama) dan <strong>resolusi</strong> (waktu dari pembuatan tiket hingga tiket ditutup). Kedua target diatur per prioritas &mdash; sehingga P1 mungkin memiliki 30 menit untuk respons dan 4 jam untuk resolusi, sedangkan P4 mungkin memiliki 8 jam kerja dan 5 hari kerja.',
            'switch_note' => 'Tidak memakai SLA? Nonaktifkan SLA di <strong>Sistem &rarr; Modul &rarr; Ketersediaan &rarr; Fitur tiket</strong>: jam, peringatan pelanggaran, dan pemicu workflow SLA berhenti, sedangkan kalender bisnis tetap ada untuk jam buka web chat. Mengaktifkannya kembali akan menanyakan apakah peringatan yang terlewat saat nonaktif dikirim, atau dilewati.',
            'p2' => 'Mesin SLA FreeITSM memiliki empat pilihan desain yang perlu dipahami:',
            'choice_business' => '<strong>Jam kerja, bukan jam dinding.</strong> Tiket P2 yang dibuat pukul 16.30 dengan target respons 1 jam tidak melanggar pukul 17.30 jika kantor tutup pukul 17.00. Jam berjalan lagi pukul 09.00 hari kerja berikutnya. Ini standar industri dan satu-satunya model yang adil ketika analis pulang di malam hari.',
            'choice_pause' => '<strong>Dapat dijeda.</strong> Saat tiket berada pada status yang ditandai "Jeda SLA" (seperti <em>Menunggu Respons</em> atau <em>Ditahan</em>), jam berhenti. Jam berjalan lagi ketika tiket kembali ke status kerja.',
            'choice_compute' => '<strong>Dihitung saat dibaca, tidak disimpan.</strong> Mesin menghitung ulang status SLA dari log audit tiket setiap kali Anda melihatnya. Tidak ada penghitung tersimpan yang bisa tidak sinkron. Jika Anda mengubah jam kalender bisnis di kemudian hari, SLA setiap tiket historis dihitung ulang terhadap jam baru saat tiket itu dilihat berikutnya.',
            'choice_cutoff' => '<strong>Batas awal penerapan.</strong> Tanggal "Terapkan SLA mulai" yang dikendalikan admin memastikan tiket yang sudah ada di sistem Anda tidak tiba-tiba dinyatakan melanggar secara retroaktif saat SLA diaktifkan. Hanya tiket yang dibuat pada atau setelah batas itu yang dilacak.',
            'tip' => 'Jika Anda baru mengenal ITIL: waktu respons berkaitan dengan pengakuan (seseorang sudah mengambil tiket); waktu resolusi berkaitan dengan penyelesaian (masalah pengguna sudah diperbaiki). Kedua jam berjalan secara independen dan memiliki target berbeda.',
        ],
        'blocks' => [
            'heading' => 'Empat elemen dasar',
            'sub' => 'Atur keempat hal ini dan pelacakan SLA sudah berjalan. Selebihnya adalah penyempurnaan opsional.',
            'cal_heading' => '1. Kalender Bisnis',
            'cal_intro' => 'Kalender menentukan kapan service desk Anda buka. Setiap kalender memiliki:',
            'cal_tz' => '<strong>Zona waktu</strong> &mdash; pengenal zona waktu IANA (mis. <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). Peralihan DST ditangani secara otomatis.',
            'cal_hours' => '<strong>Jam kerja mingguan</strong> &mdash; satu baris per hari dalam seminggu dengan kotak centang Buka dan waktu mulai / selesai. Kalender baru secara default Sen-Jum 09.00-17.00, Sab/Min tutup. Baris yang tidak ditandai Buka berarti desk tutup pada hari itu.',
            'cal_holidays' => '<strong>Hari libur</strong> &mdash; tanggal + nama opsional. Hari libur menimpa pola mingguan (desk tutup meskipun jatuh pada hari Senin).',
            'cal_default' => '<strong>Tanda default</strong> &mdash; tepat satu kalender menjadi default. Prioritas baru mewarisinya kecuali Anda menentukan lain.',
            'cal_outro' => 'Anda dapat membuat kalender sebanyak yang dibutuhkan &mdash; satu per kantor, satu per tim, satu untuk pelanggan VIP dengan jam yang diperpanjang. Kalender dipakai bersama oleh target SLA dan mesin pemeriksa pelanggaran.',
            'prio_heading' => '2. Prioritas dengan Target SLA',
            'prio_intro' => 'Di tab Prioritas (atau lewat tabel Target SLA di tab SLA), setiap prioritas dapat memiliki:',
            'prio_response' => '<strong>Target respons (menit)</strong> &mdash; berapa lama sampai tindakan analis pertama.',
            'prio_resolution' => '<strong>Target resolusi (menit)</strong> &mdash; berapa lama sampai tiket ditutup.',
            'prio_calendar' => '<strong>Kalender</strong> &mdash; kalender bisnis mana yang menjadi acuan jam prioritas ini. Biarkan kosong untuk memakai kalender default.',
            'prio_outro' => 'Mengosongkan kedua kolom target akan menonaktifkan pelacakan SLA sepenuhnya untuk prioritas itu &mdash; berguna untuk prioritas "Informasional" atau "Backlog" yang tidak memiliki tekanan waktu.',
            'pause_heading' => '3. Status Jeda SLA',
            'pause_intro' => 'Di tab Status ada kolom khusus "Jeda SLA". Tandai status apa pun yang menunjukkan tiket sedang terhambat oleh sesuatu di luar kendali tim. Kandidat yang umum adalah:',
            'pause_awaiting' => '<strong>Menunggu Respons</strong> &mdash; pelanggan berutang informasi kepada kita. Hampir selalu diterima sebagai jeda yang adil.',
            'pause_vendor' => '<strong>Ditahan (Vendor)</strong> &mdash; menunggu dukungan Microsoft / pihak ketiga.',
            'pause_change' => '<strong>Ditahan (Jendela Perubahan)</strong> &mdash; dijadwalkan untuk jendela pemeliharaan mendatang.',
            'pause_parts' => '<strong>Ditahan (Suku Cadang)</strong> &mdash; menunggu pengiriman perangkat keras.',
            'pause_warn' => 'Status "Ditahan" yang generik bisa disalahgunakan sebagai jalan keluar SLA ketika tiket sulit atau analis sedang sibuk. Jika tim Anda disiplin, ini tidak masalah. Jika tidak, pertimbangkan menggantinya dengan varian yang lebih spesifik di atas, atau andalkan dasbor <strong>Watchtower</strong> yang menandai tiket yang dijeda lebih dari 24 jam sebagai peringatan kuning.',
            'cutoff_heading' => '4. Batas Penerapan (<code>Enforce SLAs from</code>)',
            'cutoff_p1' => 'Pengaturan global yang paling penting. Sampai Anda mengisi tanggal dan waktu di sini, pelacakan SLA dinonaktifkan sepenuhnya &mdash; tidak ada jam yang berjalan, tidak ada pil di kotak masuk, tidak ada email pelanggaran yang terkirim. Mengisinya dengan tanggal dan waktu lampau mengaktifkan SLA secara retroaktif mulai titik itu. Mengisinya dengan tanggal dan waktu mendatang menjadwalkan pengaktifan.',
            'cutoff_p2' => 'Kebanyakan tim mengisinya dengan "sekarang" saat pertama kali mengaktifkan SLA &mdash; tiket yang ada mempertahankan keadaan pra-SLA, tiket baru sejak saat itu dilacak.',
        ],
        'behaviour' => [
            'heading' => 'Pengaturan perilaku',
            'sub' => 'Pengaturan ini mengatur bagaimana mesin bereaksi terhadap kasus khusus. Defaultnya masuk akal &mdash; Anda hanya perlu meninjaunya jika punya preferensi tertentu.',
            'prio_heading' => 'Saat prioritas berubah di tengah jalan',
            'prio_intro' => 'Jika tiket P3 dinaikkan menjadi P1 di tengah jalan (karena masalahnya ternyata lebih besar dari dugaan), ada tiga perilaku yang wajar:',
            'prio_forward' => '<strong>Lanjutkan (default)</strong> &mdash; pertahankan menit kerja yang sudah terpakai dan cukup ganti target. Jika tiket sudah memakai 2 jam dari target P3 8 jam, kini tiket itu memiliki 2 jam terpakai terhadap target P1 1 jam &mdash; artinya sudah melanggar. Bisa dibilang benar: masalahnya MEMANG P1 sejak awal, hanya saja tim tidak menyadarinya.',
            'prio_recompute' => '<strong>Hitung ulang</strong> &mdash; atur ulang jam dan terapkan target baru secara retroaktif sejak tiket dibuat. Perhitungan ulang yang bersih.',
            'prio_reset' => '<strong>Atur ulang</strong> &mdash; mulai jam baru dari saat prioritas berubah. Paling longgar bagi tim, tetapi pelanggan bisa merasa dirugikan jika tiket prioritas tinggi tiba-tiba mendapat jam baru yang panjang.',
            'reopen_heading' => 'Saat tiket yang sudah ditutup dibuka kembali',
            'reopen_intro' => 'Jika tiket dibuka kembali (pengguna membalas setelah penutupan):',
            'reopen_reset' => '<strong>Atur ulang (default)</strong> &mdash; mulai jam respons dan resolusi baru dari saat dibuka kembali. Perlakukan pembukaan kembali seolah-olah tiket baru.',
            'reopen_continue' => '<strong>Lanjutkan</strong> &mdash; lanjutkan dari waktu yang sudah berlalu saat penutupan. Target SLA asli tetap berlaku.',
            'first_heading' => 'Definisi respons pertama',
            'first_intro' => 'Apa yang dihitung sebagai "respons pertama" &mdash; momen yang menghentikan jam respons?',
            'first_either' => '<strong>Salah satu (default)</strong> &mdash; tindakan analis pertama dalam bentuk apa pun: email keluar, perubahan status, penugasan.',
            'first_status' => '<strong>Perubahan status</strong> &mdash; hanya perubahan status dari default yang dihitung. Lebih ketat &mdash; analis benar-benar harus mengerjakan tiket, bukan sekadar mengkliknya.',
            'first_email' => '<strong>Email keluar</strong> &mdash; hanya balasan email kepada peminta yang dihitung. Paling ketat &mdash; pelanggan harus sudah mendengar kabar dari kita.',
            'warn_heading' => 'Persentase ambang peringatan',
            'warn_body' => 'Seberapa jauh target SLA berjalan sebelum indikator berubah dari hijau menjadi kuning. Defaultnya 80% &mdash; sehingga target respons 60 menit tampil kuning pada menit ke-48. Ini juga memicu notifikasi pelanggaran bertipe peringatan.',
        ],
        'breach' => [
            'heading' => 'Notifikasi pelanggaran',
            'sub' => 'Aturan email per departemen yang dapat dikonfigurasi, yang terkirim ketika SLA mendekati pelanggaran (peringatan) atau benar-benar melanggar.',
            'intro' => 'Setiap aturan memiliki empat dimensi, semuanya independen:',
            'scope_heading' => '1. Cakupan',
            'scope_body' => 'Bisa <strong>Default</strong> (aturan berlaku untuk tiket di setiap departemen) atau <strong>departemen tertentu</strong>. Penyelesaiannya: aturan khusus departemen mengalahkan default untuk tiket di departemen itu. Tanpa aturan default, departemen yang tidak memiliki aturan khusus tidak mendapat notifikasi.',
            'trigger_heading' => '2. Pemicu',
            'trigger_body' => 'Bisa <strong>Peringatan</strong> (tiket telah melewati ambang peringatan &mdash; potensi pelanggaran) atau <strong>Pelanggaran</strong> (tiket telah melampaui targetnya &mdash; pelanggaran sebenarnya). Masing-masing adalah aturan tersendiri, sehingga Anda dapat memberi tahu orang yang berbeda untuk tiap jenis.',
            'target_heading' => '3. Target',
            'target_body' => 'Jam mana yang dipantau &mdash; <strong>Respons</strong>, <strong>Resolusi</strong>, atau <strong>Keduanya</strong>.',
            'recip_heading' => '4. Penerima',
            'recip_intro' => 'Kombinasi apa pun dari:',
            'recip_assignee' => '<strong>Penerima tugas tiket</strong> &mdash; analis yang saat ini memegang tiket. Dilewati jika belum ditugaskan.',
            'recip_teams' => '<strong>Anggota tim departemen tiket</strong> &mdash; setiap analis di tim mana pun yang tertaut ke departemen tiket. Mencakup seluruh antrean tanpa perlu memelihara milis.',
            'recip_specific' => '<strong>Analis tertentu</strong> &mdash; pola "juara SLA" / "manajer layanan" yaitu orang yang disebut namanya, bukan peran.',
            'recip_custom' => '<strong>Alamat email kustom</strong> &mdash; teks bebas dipisahkan koma. Berguna untuk kotak masuk bersama (<code>sla-alerts@company.com</code>), jembatan email Slack/Teams, atau milis.',
            'tip' => 'Setiap tiket mengirim paling banyak satu email per (target, pemicu) &mdash; worker cron mencatat apa yang sudah terkirim di tabel <code>sla_notifications_sent</code>. Jadi peringatan terkirim sekali, pelanggaran terkirim sekali, dan selesai &mdash; tanpa perulangan spam.',
            'warn' => '<strong>Tanpa aturan = tanpa email.</strong> Bahkan jika setiap tiket di sistem melanggar, tidak ada yang terkirim sampai Anda menambahkan setidaknya satu aturan. Mulailah dengan pasangan Peringatan + Pelanggaran bercakupan Default untuk mendapatkan cakupan atas semuanya.',
        ],
        'cron' => [
            'heading' => 'Menyiapkan cron job',
            'sub' => 'Skrip pemeriksa pelanggaran perlu dijalankan sesuai jadwal. Setiap 5 menit adalah titik yang ideal.',
            'p1' => 'Indikator SLA yang terlihat di UI (pil di kotak masuk, panel di panel baca) dihitung langsung saat halaman dimuat. Tetapi email pelanggaran hanya bisa terkirim jika <em>sesuatu</em> secara proaktif memeriksa tiket bahkan ketika tidak ada yang melihat. Sesuatu itu adalah tugas terjadwal &mdash; di Windows, Task Scheduler; di Linux, cron.',
            'p2' => 'Skripnya adalah <code>cron/sla_breach_check.php</code> di direktori instalasi FreeITSM. Skrip ini dapat dipanggil dengan dua cara:',
            'cli_heading' => 'A. CLI (direkomendasikan pada server yang Anda kendalikan)',
            'cli_note' => 'Tidak perlu autentikasi &mdash; izin sistem berkas sudah membatasi siapa yang bisa menjalankannya.',
            'http_heading' => 'B. HTTP (untuk shared hosting atau penjadwal jarak jauh)',
            'http_note' => 'Token dibuat otomatis saat instalasi pertama dan disimpan di <code>system_settings</code> dengan kunci <code>sla_cron_token</code> (32 karakter hex, entropi ~128 bit). Token ini dienkripsi saat disimpan, sehingga membaca barisnya langsung memberi Anda <code>ENC:…</code> alih-alih token. Temukan milik Anda dengan:',
            'win_heading' => 'Windows Task Scheduler',
            'win_intro' => 'Buka Task Scheduler (<code>taskschd.msc</code>) dan buat tugas baru dengan pengaturan berikut:',
            'tbl_field' => 'Bidang',
            'tbl_value' => 'Nilai',
            'win_r1_k' => 'Nama',
            'win_r1_v' => 'FreeITSM &mdash; Pemeriksaan Pelanggaran SLA',
            'win_r2_k' => 'Jalankan baik pengguna masuk maupun tidak',
            'win_r2_v' => 'Centang ini',
            'win_r3_k' => 'Pemicu',
            'win_r3_v' => 'Harian, ulangi setiap 1 hari, ulangi setiap 5 menit selama 1 hari',
            'win_r4_k' => 'Tindakan',
            'win_r4_v' => 'Mulai program',
            'win_r5_k' => 'Program/skrip',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'Tambahkan argumen',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'Mulai di',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Cron Linux',
            'linux_intro' => 'Tambahkan satu baris ke crontab Anda (<code>crontab -e</code>):',
            'sec_heading' => 'Keamanan &mdash; yang melindungi endpoint HTTP',
            'sec_intro' => 'Tiga lapis, semuanya diterapkan secara otomatis:',
            'sec_token' => '<strong>1. Token rahasia bersama</strong> &mdash; acak 128 bit per instalasi, dibandingkan dengan pencocokan waktu konstan untuk mencegah serangan pengaturan waktu.',
            'sec_lockout' => '<strong>2. Penguncian autentikasi gagal per IP</strong> &mdash; lebih dari 10 percobaan token salah dari IP yang sama dalam satu jam terakhir memicu penguncian 429 selama 1 jam. Menggagalkan penelusuran brute-force tanpa perlu fail2ban.',
            'sec_interval' => '<strong>3. Interval minimum antar eksekusi yang berhasil</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (default 30 dtk). Bahkan permintaan dengan token valid mendapat 429 jika tiba lebih cepat dari ini setelah eksekusi berhasil terakhir. Mencegah penjadwalan ganda yang tidak disengaja dan perulangan tak terkendali.',
            'log_heading' => 'Log aktivitas',
            'log_body' => 'Setiap pemanggilan (diterima atau ditolak) dicatat ke tabel <code>sla_cron_runs</code> dengan waktu, hasil, jumlah, dan IP klien. Lihat 20 eksekusi terakhir di panel <strong>Aktivitas Cron</strong> di bagian bawah tab pengaturan SLA &mdash; berguna untuk memastikan jadwal berjalan dan untuk mengaudit percobaan autentikasi yang gagal. Baris dihapus otomatis setelah <code>sla_cron_log_retention_days</code> (default 30) sehingga tabel tetap kecil.',
        ],
        'examples' => [
            'heading' => 'Contoh kasus',
            'sub' => 'Dari kasus satu zona waktu yang sederhana hingga kasus lintas zona waktu yang lebih rumit di mana "adil" perlu didefinisikan.',
            'ex1_heading' => 'Contoh 1: Tiket dibuat di Inggris, service desk di Inggris',
            'ex1_title' => 'Kasus sederhana',
            'ex1_tag' => 'satu zona waktu',
            'ex1_setup' => '<strong>Pengaturan:</strong> Satu kalender bisnis bernama <em>UK Office</em> dengan zona waktu <code>Europe/London</code>, Sen-Jum 09.00-17.00, tanpa hari libur. Prioritas P2 memiliki target respons 1 jam dan target resolusi 4 jam, keduanya berjalan terhadap kalender <em>UK Office</em>.',
            'ex1_scenario' => '<strong>Skenario:</strong> Pengguna membuat tiket P2 pada <strong>pukul 16.30 waktu Inggris hari Rabu</strong>.',
            'ex1_timeline' => 'Rab 16.30 Inggris &mdash; <strong>tiket dibuat</strong>, jam respons mulai.
Rab 17.00 Inggris &mdash; kantor tutup, jam dijeda (30 menit terpakai dari target 60 menit).
Kam 09.00 Inggris &mdash; kantor buka, jam berjalan lagi.
Kam 09.30 Inggris &mdash; analis membalas. SLA respons terpenuhi tepat di batas (60 menit terpakai, target 60 menit).',
            'ex1_outro' => 'Jika analis baru membalas pada <strong>Kamis pukul 10.00 Inggris</strong>, respons akan <strong>melanggar sebesar 30 menit</strong> (90 menit terpakai terhadap target 60 menit &mdash; 30 dari Rabu sore, 60 dari Kamis pagi). Jam 1 jam hanya berjalan selama jam kerja, tetapi tiket di akhir hari tetap menghabiskan sebagian besar anggarannya semalaman saat kantor buka lagi &mdash; analis yang tiba pukul 09.00 mudah mengira masih punya satu jam penuh, padahal hanya tersisa 30 menit.',
            'ex2_heading' => 'Contoh 2: Tiket dibuat di Inggris, service desk di Estonia',
            'ex2_title' => 'Kasus lintas zona waktu',
            'ex2_tag' => '3 cara mendefinisikan "adil"',
            'ex2_setup' => '<strong>Pengaturan:</strong> Pelanggan Inggris (<code>Europe/London</code>, GMT/BST), service desk Estonia (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>2 jam lebih awal dari Inggris</strong>). Kedua desk secara nominal bekerja pukul 09.00-17.00 waktu setempat.',
            'ex2_scenario' => '<strong>Skenario:</strong> Pelanggan Inggris membuat tiket P2 pada <strong>pukul 16.30 waktu Inggris hari Jumat</strong> (= 18.30 Estonia, setelah Estonia tutup). Kesempatan berikutnya bagi analis Estonia untuk mengerjakannya adalah Senin 09.00 Estonia (= 07.00 Inggris). Target respons adalah 1 jam.',
            'ex2_question' => 'Apa yang seharusnya dikatakan SLA? Ada tiga jawaban yang dapat dipertanggungjawabkan, masing-masing adil dalam arti yang berbeda. Anda memilih kalender mana yang ditetapkan ke prioritas berdasarkan apa yang dijanjikan kontrak layanan Anda.',
            'optA_label' => 'Opsi A &mdash; Berpusat pada pelanggan',
            'optA_p1' => '<strong>Atur prioritas agar memakai kalender dengan jam <em>Inggris</em>.</strong> Jam berjalan terhadap 09.00-17.00 Inggris, di mana pun analis berada.',
            'optA_p2' => 'Dalam skenario di atas, tiket dibuat pukul 16.30 Inggris hari Jumat: jam berjalan 16.30&ndash;17.00 Inggris hari Jumat (30 menit terpakai), dijeda semalaman + akhir pekan, berjalan lagi Sen 09.00 Inggris. Jika analis Estonia membalas pukul 10.00 Estonia hari Senin (= 08.00 Inggris), kalender Inggris masih dijeda (kantor Inggris buka pukul 09.00 Inggris), sehingga tidak ada menit tambahan yang berjalan &mdash; pemakaian tetap 30 menit. <strong>SLA terpenuhi dengan margin 30 menit</strong>. Balasan apa pun setelah 09.30 Inggris (= 11.30 Estonia) akan melanggar.',
            'optA_p3' => '<em>Adil bagi:</em> pelanggan. Pengalaman mereka sesuai dengan hari kerja mereka.<br><em>Kompromi:</em> analis Estonia diharapkan tersedia pukul 09.00-17.00 waktu Inggris (= 11.00-19.00 Estonia), yang memperpanjang hari kerja mereka 2 jam.',
            'optB_label' => 'Opsi B &mdash; Berpusat pada analis',
            'optB_p1' => '<strong>Atur prioritas agar memakai kalender dengan jam <em>Estonia</em>.</strong> Jam berjalan terhadap 09.00-17.00 Estonia.',
            'optB_p2' => 'Skenario yang sama: tiket dibuat 18.30 Estonia hari Jumat (setelah tutup), jam dijeda sepanjang akhir pekan, mulai berjalan Sen 09.00 Estonia (= 07.00 Inggris). Jika analis merespons pukul 09.30 Estonia hari Senin (= 07.30 Inggris), SLA respons telah memakai 30 menit dari target 60 menit &mdash; <strong>terpenuhi dengan margin 30 menit</strong>. Pelanggan Inggris yang membuat tiket pukul 16.30 Inggris hari Jumat dan mendapat balasan pukul 07.30 Inggris hari Senin &mdash; waktu tunggu sebenarnya jauh lebih lama daripada yang disiratkan SLA.',
            'optB_p3' => '<em>Adil bagi:</em> para analis. Mereka bekerja pada jam normal.<br><em>Kompromi:</em> Pelanggan di Inggris bisa merasa SLA "berbohong" jika tiket Jumat sore baru dijawab Senin pagi waktu Estonia tetapi laporan menyatakan SLA respons 1 jam. Pastikan kontrak layanan Anda secara eksplisit menyebut bahwa SLA berjalan terhadap jam support desk.',
            'optC_label' => 'Opsi C &mdash; Jendela tumpang tindih (paling ketat)',
            'optC_p1' => '<strong>Atur prioritas agar memakai kalender yang hanya mencakup jam ketika kedua desk buka.</strong> 09.00-17.00 Inggris tumpang tindih dengan 09.00-17.00 Estonia (= 07.00-15.00 Inggris) pada <strong>jendela 09.00-15.00 Inggris</strong> &mdash; 6 jam per hari kerja.',
            'optC_p2' => 'Skenario yang sama: tiket dibuat 16.30 Inggris hari Jumat (di luar tumpang tindih, karena tumpang tindih berakhir pukul 15.00 Inggris), jam dijeda sepanjang akhir pekan, berjalan lagi Sen 09.00 Inggris (= 11.00 Estonia, saat tumpang tindih dibuka lagi). Jika analis Estonia membalas pukul 11.30 Estonia (= 09.30 Inggris), SLA respons telah memakai 30 menit dari target 60 menit &mdash; <strong>terpenuhi dengan margin 30 menit</strong>. Balasan terjadi selama jendela tumpang tindih sehingga langsung dihitung.',
            'optC_p3' => '<em>Adil bagi:</em> kedua pihak &mdash; SLA hanya berjalan selama jam ketika desk benar-benar bisa memajukan tiket DAN pelanggan berada di mejanya untuk menerima respons.<br><em>Kompromi:</em> Jendela harian yang lebih pendek berarti waktu sebenarnya lebih lama untuk memenuhi target yang agresif. Target resolusi 4 jam mencakup 1,5 hari tumpang tindih, sedangkan dengan kalender normal 8 jam akan selesai dalam satu hari.',
            'choose_tip' => '<strong>Cara memilih:</strong> Lihat kontrak layanan Anda. Jika berbunyi "respons dalam 1 jam sejak diterima" &mdash; itu Opsi A (jam pelanggan). Jika berbunyi "respons dalam 1 jam kerja" &mdash; itu biasanya Opsi B (desk mana pun yang sedang bekerja). Jika berbunyi "dalam 1 jam ketersediaan bersama" &mdash; itu Opsi C. Jika tidak ada kontrak, tanyakan kepada tim: apakah Anda ingin merasakan tekanan di luar jam Estonia (Opsi A), atau Anda ingin pelanggan Inggris sesekali merasa diabaikan (Opsi B)?',
            'ex3_heading' => 'Contoh 3: Jeda jam selama menunggu vendor',
            'ex3_title' => 'Bagaimana status jeda bekerja dalam praktik',
            'ex3_tag' => 'jeda jam',
            'ex3_setup' => '<strong>Pengaturan:</strong> Prioritas P3 dengan target resolusi 8 jam kerja, kalender Inggris, status "Menunggu Vendor" ditandai <em>Jeda SLA</em>.',
            'ex3_scenario' => '<strong>Skenario:</strong> Tiket dibuat Sen 09.00 Inggris. Analis mengeskalasi ke Microsoft pada Sen 11.00 Inggris dan memindahkan tiket ke "Menunggu Vendor". Microsoft merespons Rab 14.00 Inggris. Analis menerapkan perbaikan dan menutup pada Kam 10.00 Inggris.',
            'ex3_timeline' => 'Sen 09.00 &mdash; tiket dibuat, jam resolusi berjalan.
Sen 11.00 &mdash; dipindahkan ke "Menunggu Vendor", <strong>jam dijeda</strong> (2 jam terpakai).
Rab 14.00 &mdash; dipindahkan kembali ke "Sedang Dikerjakan", <strong>jam berjalan lagi</strong>.
Rab 17.00 &mdash; kantor tutup (total 5 jam terpakai).
Kam 09.00 &mdash; kantor buka.
Kam 10.00 &mdash; tiket ditutup (total 6 jam terpakai). <strong>SLA terpenuhi</strong> terhadap target 8 jam.',
            'ex3_outro' => 'Waktu sebenarnya yang berlalu: ~3 hari. Waktu SLA yang berlalu: 6 jam kerja. Tanpa tanda status jeda, SLA akan menghitung seluruh 2 hari menunggu vendor + jam kerja, totalnya ~18 jam kerja &mdash; jauh melewati batas pelanggaran.',
        ],
        'trouble' => [
