            'r2_c' => 'Periksa riwayat perubahan prioritas &mdash; jika prioritas dinaikkan di tengah jalan dan perilaku diatur ke "Lanjutkan" (default), waktu yang sudah terpakai terbawa.',
            'r3_s' => 'Notifikasi pelanggaran tidak terkirim',
