            'r4_s' => 'Cron berjalan tetapi melaporkan "no matching rule"',
            'r4_c' => 'Tambahkan setidaknya satu aturan bercakupan Default agar setiap departemen tercakup.',
            'r5_s' => 'Watchtower menampilkan "N tickets paused over 24h"',
            'r5_c' => 'Tiket berada pada status jeda SLA. Entah seseorang sengaja memarkirnya lalu lupa, atau seseorang memakai Ditahan sebagai jalan keluar SLA. Buka masing-masing dan teruskan prosesnya atau singkirkan status jeda.',
            'r6_s' => 'Cron HTTP mengembalikan 403',
